def h(value: object) -> str:
    return html.escape("" if value is None else str(value), quote=True)


def label_status(value: object) -> str:
    if value is None:
        return ""
    text = str(value)
    return STATUS_LABELS.get(text, text)


def priority_label(value: object) -> str:
    text = "" if value is None else str(value).strip()
    if text.upper().startswith("P"):
        text = text[1:]
    try:
        number = int(text)
    except ValueError:
        return "Infektverdacht"
    labels = {
        1: "Hoher Infektverdacht",
        2: "Erweiterter Prüfbedarf",
        3: "Niedrigerer Prüfbedarf",
        4: "Nachrangig prüfen",
    }
    return labels.get(number, f"Priorität {number}")


def fmt_int(value: object) -> str:
    try:
        return f"{int(value or 0):,}".replace(",", ".")
    except (TypeError, ValueError):
        return "0"


def first(value: list[str] | None, default: str = "") -> str:
    if not value:
        return default
    return value[0].strip()


def safe_filename_part(value: object, fallback: str) -> str:
    text = re.sub(r"[^A-Za-z0-9_.-]+", "_", str(value or "").strip()).strip("._-")
    return text[:80] or fallback


def int_or_none(value: str | None) -> int | None:
    if value is None or value == "":
        return None
    try:
        return int(value)
    except ValueError:
        return None


def float_or_none(value: str | None) -> float | None:
    if value is None or value.strip() == "":
        return None
    try:
        return float(value.strip().replace(",", "."))
    except ValueError:
        return None


def administrations_per_day(interval: object) -> float | None:
    text = str(interval or "").strip().lower().replace("×", "x")
    if not text:
        return None
    schedule = re.fullmatch(r"\s*(\d+(?:[.,]\d+)?)\s*-\s*(\d+(?:[.,]\d+)?)\s*-\s*(\d+(?:[.,]\d+)?)\s*(?:-\s*(\d+(?:[.,]\d+)?))?\s*", text)
    if schedule:
        return sum(float(value.replace(",", ".")) for value in schedule.groups() if value is not None)
    times = re.search(r"(\d+(?:[.,]\d+)?)\s*(?:x|mal)\s*(?:tgl|täglich|tag)?", text)
    if times:
        return float(times.group(1).replace(",", "."))
    hours = re.search(r"alle\s*(\d+(?:[.,]\d+)?)\s*h", text)
    if hours:
        value = float(hours.group(1).replace(",", "."))
        return 24 / value if value > 0 else None
    return None


def calculated_daily_dose(single_dose: object, interval: object) -> tuple[float | None, float | None]:
    dose = float_or_none(str(single_dose or ""))
    administrations = administrations_per_day(interval)
    if dose is None or administrations is None:
        return administrations, None
    return administrations, round(dose * administrations, 6)


def split_dose_value_unit(value: object) -> tuple[str, str]:
    text = str(value or "").strip()
    match = re.fullmatch(r"\s*(\d+(?:[.,]\d+)?)\s*([^\d].*)?", text)
    if not match:
        return "", text
    return match.group(1), str(match.group(2) or "").strip()


def format_decimal(value: float | None) -> str:
    if value is None:
        return ""
    return f"{value:.12g}"


def date_or_none(value: object) -> date | None:
    if not value:
        return None
    try:
        return date.fromisoformat(str(value)[:10])
    except ValueError:
        return None


def checked(form: dict[str, list[str]], name: str) -> int:
    return 1 if first(form.get(name)) else 0


def iso_date_or_blank(value: object) -> str:
    if not value:
        return ""
    text = str(value).strip()
    if not text:
        return ""
    try:
        return date.fromisoformat(text[:10]).isoformat()
    except ValueError:
        pass
    match = DATE_PATTERN.search(text)
    if not match:
        return ""
    raw = match.group(1).replace(".", "-").replace("/", "-")
    parts = raw.split("-")
    try:
        if len(parts[0]) == 4:
            year, month, day = int(parts[0]), int(parts[1]), int(parts[2])
        else:
            day, month, year = int(parts[0]), int(parts[1]), int(parts[2])
            if year < 100:
                year += 2000 if year < 40 else 1900
        return date(year, month, day).isoformat()
    except (ValueError, IndexError):
        return ""


def human_date(value: object) -> str:
    parsed = date_or_none(value)
    if not parsed:
        return str(value or "").strip()
    return f"{parsed.day}. {GERMAN_MONTHS[parsed.month]} {parsed.year}"


def numeric_date(value: object) -> str:
    parsed = date_or_none(value)
    return parsed.strftime("%d.%m.%Y") if parsed else str(value or "").strip()


def human_date_range(start: object, end: object, *, fallback: str = "") -> str:
    start_date = date_or_none(start)
    end_date = date_or_none(end)
    if start_date and end_date:
        if end_date < start_date:
            return f"Datum prüfen: {human_date(start_date)} / {human_date(end_date)}"
        if start_date == end_date:
            return human_date(start_date)
        if start_date.year == end_date.year and start_date.month == end_date.month:
            return f"{start_date.day}.-{end_date.day}. {GERMAN_MONTHS[start_date.month]} {start_date.year}"
        if start_date.year == end_date.year:
            return (
                f"{start_date.day}. {GERMAN_MONTHS[start_date.month]} "
                f"bis {end_date.day}. {GERMAN_MONTHS[end_date.month]} {start_date.year}"
            )
        return f"{human_date(start_date)} bis {human_date(end_date)}"
    if start_date:
        return f"ab {human_date(start_date)}"
    if end_date:
        return f"bis {human_date(end_date)}"
    return fallback


def therapy_duration_days(start: object, end: object) -> int | None:
    start_date = date_or_none(start)
    end_date = date_or_none(end)
    if not start_date or not end_date or end_date < start_date:
        return None
    return (end_date - start_date).days + 1


def format_duration(value: object) -> str:
    try:
        days = int(value)
    except (TypeError, ValueError):
        return ""
    if days <= 0:
        return ""
    return f"{days} Tag" if days == 1 else f"{days} Tage"


def short_list(raw: object, *, max_chars: int = 500) -> str:
    if raw is None:
        return ""
    parts = []
    seen = set()
    for part in str(raw).split(","):
        text = part.strip()
        if not text or text in seen:
            continue
        seen.add(text)
        parts.append(text)
    joined = "; ".join(parts)
    if len(joined) <= max_chars:
        return joined
    return joined[: max_chars - 3].rstrip() + "..."


def compact_text(raw: object, *, max_chars: int = 500) -> str:
    if raw is None:
        return ""
    text = re.sub(r"\s+", " ", str(raw)).strip(" ;:-")
    text = re.sub(r"(?:;\s*){2,}", "; ", text).strip(" ;:-")
    if len(text) <= max_chars:
        return text
    return text[: max_chars - 3].rstrip() + "..."


def normalized_medication_text(*values: object) -> str:
    return " ".join(str(value or "").strip().lower() for value in values if value).strip()


def is_antibiotic_name(name: object) -> bool:
    text = normalized_medication_text(name)
    if not text:
        return False
    for entry in load_lexicon():
        for term in entry.terms:
            if term and candidate_pattern(term).search(text):
                return True
    return False


def infer_medication_category(name: object, raw: object = "") -> str:
    text = normalized_medication_text(name, raw)
    if is_antibiotic_name(text):
        return "antibiotikum"
    for category, terms in MEDICATION_CATEGORY_RULES:
        if any(term in text for term in terms):
            return category
    return "sonstiges"


def medication_category_label(value: object) -> str:
    category = str(value or "").strip().lower() or "sonstiges"
    return MEDICATION_CATEGORY_LABELS.get(category, category)


def medication_drug_class(name: object) -> str:
    """Return a controlled pharmacological class for a recognized medicine."""
    text = normalized_medication_text(name)
    if not text:
        return ""
    for entry in load_lexicon():
        if any(term and candidate_pattern(term).search(text) for term in entry.terms):
            return str(entry.klasse or "").strip()
    for terms, class_label in MEDICATION_PRODUCT_CLASSES:
        if any(term in text for term in terms):
            return class_label
    return ""


def medication_category_sort_key(value: object) -> int:
    category = str(value or "").strip().lower() or "sonstiges"
    return MEDICATION_CATEGORY_ORDER.get(category, MEDICATION_CATEGORY_ORDER["sonstiges"])


