def date_gap_notice(op_date: str | None, culture_date: str | None) -> str:
    if not op_date or not culture_date:
        return ""
    try:
        op = date.fromisoformat(str(op_date)[:10])
        culture = date.fromisoformat(str(culture_date)[:10])
    except ValueError:
        return ""
    days = abs((culture - op).days)
    if days <= 180:
        return ""
    years = days / 365.25
    if years >= 1:
        text = f"Zuordnung prüfen: Kultur ca. {years:.1f} Jahre von OP entfernt"
    else:
        text = f"Zuordnung prüfen: Kultur {days} Tage von OP entfernt"
    return f'<div class="case-notice">{h(text)}</div>'


def client_script() -> str:
    return """
<script>
(() => {
  let activeZone = null;
  const scrollRestoreKey = 'pji-scroll-restore';

  function rememberScrollPosition(form) {
    try {
      const scope = form && (form.closest('.stay-row, .patientenbrief-card, .intervention-row, .entry-step') || form);
      sessionStorage.setItem(scrollRestoreKey, JSON.stringify({
        path: window.location.pathname,
        y: window.scrollY,
        hash: window.location.hash || '',
        targetId: scope && scope.id ? scope.id : '',
        createdAt: Date.now()
      }));
    } catch {}
  }

  function restoreScrollPosition() {
    let raw = null;
    try {
      raw = sessionStorage.getItem(scrollRestoreKey);
      sessionStorage.removeItem(scrollRestoreKey);
    } catch {
      return false;
    }
    if (!raw) return false;
    try {
      const saved = JSON.parse(raw);
      if (!saved || saved.path !== window.location.pathname) return false;
      if (Date.now() - Number(saved.createdAt || 0) > 30000) return false;
      window.setTimeout(() => {
        if (saved.targetId) {
          const target = document.getElementById(saved.targetId);
          if (target) {
            target.scrollIntoView({ block: 'start' });
            return;
          }
        }
        window.scrollTo(0, Math.max(0, Number(saved.y) || 0));
      }, 80);
      return true;
    } catch {
      return false;
    }
  }

  function setState(zone, text, stateClass) {
    const state = zone.querySelector('.paste-state');
    if (!state) return;
    state.textContent = text;
    state.classList.remove('ok', 'warn', 'bad');
    if (stateClass) state.classList.add(stateClass);
  }

	  function payloadFor(zone, dataUrl, file) {
	    const form = zone.closest('form');
	    const fallbackScope = form || zone.closest('.quiet-details-body, .stay-edit-details, .entry-step, section') || document;
	    const valueFromForm = (name) => {
	      const field = fallbackScope && fallbackScope.querySelector(`[name="${name}"]`);
	      return field && field.value ? field.value : '';
	    };
    return {
      image_data: dataUrl,
      filename: zone.dataset.filename || (file && file.name) || 'fieberkurve.png',
      episode_id: zone.dataset.episodeId || '',
      eingriff_id: valueFromForm('eingriff_id') || zone.dataset.eingriffId || '',
      aufenthalt_id: valueFromForm('aufenthalt_id') || zone.dataset.aufenthaltId || '',
      fallnummer: valueFromForm('fallnummer'),
      aufnahme: valueFromForm('aufnahme'),
      entlassung: valueFromForm('entlassung'),
      replace_existing: zone.dataset.replaceExisting || '',
      op_datum: valueFromForm('op_datum'),
      dokument_datum: valueFromForm('dokument_datum'),
      eingriff_zusammenfassung: valueFromForm('eingriff_zusammenfassung'),
      diagnose_text: valueFromForm('diagnose_text'),
      operateur: valueFromForm('operateur'),
      op_assistent: valueFromForm('op_assistent'),
      legholder: valueFromForm('legholder'),
      anaesthesist: valueFromForm('anaesthesist'),
      instrumentation: valueFromForm('instrumentation'),
      lagerung_narkose: valueFromForm('lagerung_narkose'),
      zugang: valueFromForm('zugang'),
      proben_text: valueFromForm('proben_text'),
      implantat_text: valueFromForm('implantat_text'),
      kommentar: valueFromForm('kommentar'),
      bericht_text: valueFromForm('bericht_text') || valueFromForm('patientenbrief_text')
    };
  }

  function patientenbriefZone(zone) {
    return (zone.dataset.uploadUrl || '').includes('patientenbrief');
  }

  function opberichtZone(zone) {
    return (zone.dataset.uploadUrl || '').includes('opbericht');
  }

  function ambulanzZone(zone) {
    return (zone.dataset.uploadUrl || '').includes('ambulanz');
  }

  function praeopZone(zone) {
    return (zone.dataset.uploadUrl || '').includes('praeop');
  }

  function histologyZone(zone) {
    return (zone.dataset.uploadUrl || '').includes('histo');
  }

  function textUploadZone(zone) {
    return patientenbriefZone(zone) || opberichtZone(zone) || ambulanzZone(zone) || praeopZone(zone) || histologyZone(zone);
  }

  function collectPagesZone(zone) {
    return zone && zone.dataset.collectPages === '1';
  }

  function escapeHtml(value) {
    return String(value || '').replace(/[&<>"']/g, (character) => ({
      '&': '&amp;',
      '<': '&lt;',
      '>': '&gt;',
      '"': '&quot;',
      "'": '&#039;'
    }[character]));
  }

  function queuedPages(input) {
    if (!input) return [];
    try {
      const decoded = JSON.parse(input.value || '[]');
      return Array.isArray(decoded) ? decoded : [];
    } catch {
      return [];
    }
  }

  function renderQueuedPages(form) {
    const input = form && form.querySelector('[data-pages-json]');
    const list = form && form.querySelector('[data-page-list]');
    if (!input || !list) return;
    const pages = queuedPages(input);
    list.hidden = pages.length === 0;
    list.innerHTML = pages.map((page, index) => `
      <span class="page-chip">
        <span>Seite ${index + 1}: ${escapeHtml(page.filename || 'Screenshot')}</span>
        <button type="button" data-remove-page="${index}" aria-label="Seite entfernen">x</button>
      </span>
    `).join('');
    if (form.classList.contains('op-report-form')) {
      const previewButton = form.querySelector('[data-op-preview]');
      const previewState = form.querySelector('.op-preview-state');
      if (previewButton) {
        previewButton.textContent = pages.length ? 'Seiten speichern und auslesen' : 'Text auslesen';
      }
      if (previewState && pages.length) {
        previewState.textContent = `${pages.length} Seite(n) werden gemeinsam als ein OP-Bericht gespeichert und ausgelesen`;
        previewState.classList.remove('bad', 'warn');
        previewState.classList.add('ok');
      }
    }
  }

  function collectDocumentPage(zone, file) {
    const type = file && file.type ? file.type : '';
    const textFile = file && (type === 'text/plain' || /\\.txt$/i.test(file.name || ''));
    if (!file || !(type.startsWith('image/') || type === 'application/pdf' || textFile)) {
      setState(zone, 'Nur Bild, PDF oder Text', 'bad');
      return;
    }
    if (textFile) {
      const textReader = new FileReader();
      textReader.onload = () => {
        if (appendTextToFormTextarea(zone, String(textReader.result || ''))) {
          setState(zone, 'Text eingefügt - dann Patientenbrief auslesen', 'ok');
        } else {
          setState(zone, 'Textfeld nicht gefunden', 'bad');
        }
      };
      textReader.onerror = () => setState(zone, 'Textdatei konnte nicht gelesen werden', 'bad');
      textReader.readAsText(file);
      return;
    }

    const form = zone.closest('form');
    const input = form && form.querySelector('[data-pages-json]');
    if (!input) {
      setState(zone, 'Seitenspeicher nicht gefunden', 'bad');
      return;
    }
    const pages = queuedPages(input);
    if (pages.length >= 20) {
      setState(zone, 'Maximal 20 Seiten pro Dokument', 'bad');
      return;
    }
    setState(zone, 'Seite wird vorgemerkt...', 'warn');
    const reader = new FileReader();
    reader.onload = () => {
      pages.push({
        filename: file.name || `dokument_seite_${pages.length + 1}.png`,
        type,
        size: file.size || 0,
        dataUrl: reader.result
      });
      input.value = JSON.stringify(pages);
      renderQueuedPages(form);
      const label = opberichtZone(zone) ? 'OP-Bericht speichern und auslesen' : praeopZone(zone) ? 'Auslesen lassen' : ambulanzZone(zone) ? 'Ambulanzkartei speichern und auslesen' : histologyZone(zone) ? 'Histologie speichern und auslesen' : 'Patientenbrief auslesen';
      setState(zone, `${pages.length} Seite(n) bereit - dann ${label}`, 'ok');
    };
    reader.onerror = () => setState(zone, 'Datei konnte nicht gelesen werden', 'bad');
    reader.readAsDataURL(file);
  }

  function uploadBlob(zone, file) {
    if (collectPagesZone(zone)) {
      collectDocumentPage(zone, file);
      return;
    }
    const type = file && file.type ? file.type : '';
    const textFile = file && (type === 'text/plain' || /\\.txt$/i.test(file.name || ''));
    if (!file || !(type.startsWith('image/') || type === 'application/pdf' || (textUploadZone(zone) && textFile))) {
      setState(zone, textUploadZone(zone) ? 'Nur Bild, PDF oder Text' : 'Nur Bild oder PDF', 'bad');
      return;
    }
    const appendingFeverPage = (zone.dataset.uploadUrl || '').includes('append-page-clipboard');
    setState(zone, appendingFeverPage ? 'Blatt wird gespeichert...' : 'Import und OCR laufen...', 'warn');
    const reader = new FileReader();
    reader.onload = async () => {
      try {
        const response = await fetch(zone.dataset.uploadUrl || '/clipboard-upload', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payloadFor(zone, reader.result, file))
        });
        const result = await response.json();
        if (!response.ok || !result.ok) {
          throw new Error(result.error || 'Import fehlgeschlagen');
        }
        const importedId = result.fieberkurve_id || result.praeop_id || result.patientenbrief_id || result.opbericht_id || result.ambulanz_id || '';
        const appendedFeverPage = (zone.dataset.uploadUrl || '').includes('append-page-clipboard');
        setState(zone, appendedFeverPage || result.staged ? 'Blatt gespeichert – noch nicht ausgelesen' : (importedId ? `importiert #${importedId}` : 'importiert'), 'ok');
        const target = zone.querySelector('.review-link');
        const targetUrl = result.review_url || result.detail_url || '';
        if (target) {
          target.href = targetUrl;
          target.hidden = false;
        }
        if (zone.dataset.autoOpen === '1' && targetUrl) {
          window.location.href = targetUrl;
        }
      } catch (error) {
        setState(zone, error.message || 'Import fehlgeschlagen', 'bad');
      }
    };
    reader.onerror = () => setState(zone, 'Datei konnte nicht gelesen werden', 'bad');
    reader.readAsDataURL(file);
  }

  async function uploadTextDocument(zone, text) {
    if (!text || text.trim().length < 10) {
      setState(zone, 'Kein Text in der Zwischenablage', 'bad');
      return;
    }
    const defaultName = opberichtZone(zone) ? 'OP-Bericht.txt' : ambulanzZone(zone) ? 'Ambulanzkartei.txt' : praeopZone(zone) ? 'Praeop-Anamnese.txt' : 'Patientenbrief.txt';
    const label = opberichtZone(zone) ? 'OP-Bericht' : ambulanzZone(zone) ? 'Ambulanzkartei' : praeopZone(zone) ? 'Präop-Anamnese' : 'Brief';
    setState(zone, `${label} wird ausgelesen...`, 'warn');
    try {
      const payload = payloadFor(zone, '', { name: defaultName, type: 'text/plain' });
      payload.bericht_text = text.trim();
      payload.filename = payload.filename || defaultName;
      const response = await fetch(zone.dataset.uploadUrl || '', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      });
      const result = await response.json();
      if (!response.ok || !result.ok) {
        throw new Error(result.error || 'Import fehlgeschlagen');
      }
      const importedId = result.patientenbrief_id || result.opbericht_id || result.ambulanz_id || '';
      setState(zone, importedId ? `importiert #${importedId}` : 'importiert', 'ok');
      const targetUrl = result.detail_url || '';
      if (zone.dataset.autoOpen === '1' && targetUrl) {
        window.location.href = targetUrl;
      }
    } catch (error) {
      setState(zone, error.message || 'Import fehlgeschlagen', 'bad');
    }
  }

	  function appendTextToFormTextarea(zone, text) {
	    const form = zone.closest('form');
	    const fallbackScope = form || zone.closest('.quiet-details-body, .stay-edit-details, .entry-step, section');
	    if (!fallbackScope || !text || !text.trim()) return false;
	    const textarea = fallbackScope.querySelector('[name="bericht_text"]') || fallbackScope.querySelector('[name="patientenbrief_text"]');
	    if (!textarea) return false;
    const clean = text.trim();
    const separator = textarea.value.trim() ? '\\n\\n--- weitere Seite / weiterer Text ---\\n\\n' : '';
    textarea.value = `${textarea.value}${separator}${clean}`;
    textarea.dispatchEvent(new Event('input', { bubbles: true }));
	    if (form && form.classList.contains('op-report-form')) {
      window.clearTimeout(opPreviewTimer);
      opPreviewTimer = window.setTimeout(() => previewOpReport(form), 120);
    }
    setState(zone, 'Text eingefügt - weitere Seiten möglich, dann speichern', 'ok');
    textarea.focus();
    textarea.setSelectionRange(textarea.value.length, textarea.value.length);
    return true;
  }

	  function pickClipboardImage(event) {
	    const items = event.clipboardData && Array.from(event.clipboardData.items || []);
	    if (!items || !items.length) return null;
	    const item = items.find((candidate) => candidate.type && (candidate.type.startsWith('image/') || candidate.type === 'application/pdf'));
	    return item ? item.getAsFile() : null;
	  }

	  function isTextEntryTarget(element) {
	    if (!element || !element.matches) return false;
	    return element.matches('textarea, input:not([type="file"]), [contenteditable="true"]');
	  }

	  function usablePasteZone(zone) {
	    if (!zone) return false;
	    const rect = zone.getBoundingClientRect();
	    return rect.width > 0 && rect.height > 0;
	  }

	  function nearestPasteZone(element) {
	    if (!element || !element.closest) return null;
	    const direct = element.closest('.paste-zone');
	    if (usablePasteZone(direct)) return direct;
	    const scopes = ['.action-panel', 'form', '.quiet-details-body', '.stay-edit-details', '.entry-step', 'section'];
	    for (const selector of scopes) {
	      const scope = element.closest(selector);
	      if (!scope) continue;
	      const zone = Array.from(scope.querySelectorAll('.paste-zone')).find(usablePasteZone);
	      if (zone) return zone;
	    }
	    return null;
	  }

  document.querySelectorAll('.paste-zone').forEach((zone) => {
    zone.addEventListener('focus', () => { activeZone = zone; zone.classList.add('active'); });
    zone.addEventListener('blur', () => zone.classList.remove('active'));
    zone.addEventListener('click', () => { activeZone = zone; zone.focus(); });
    zone.addEventListener('dragover', (event) => {
      event.preventDefault();
      zone.classList.add('dragover');
    });
    zone.addEventListener('dragleave', () => zone.classList.remove('dragover'));
    zone.addEventListener('drop', (event) => {
      event.preventDefault();
      zone.classList.remove('dragover');
      const files = event.dataTransfer && event.dataTransfer.files ? Array.from(event.dataTransfer.files) : [];
      if (collectPagesZone(zone)) {
        files.forEach((file) => uploadBlob(zone, file));
      } else {
        uploadBlob(zone, files[0]);
      }
    });
  });

  document.querySelectorAll('.paste-file').forEach((input) => {
    input.addEventListener('change', () => {
      const zone = input.closest('.action-panel').querySelector('.paste-zone');
      const files = input.files ? Array.from(input.files) : [];
      if (collectPagesZone(zone)) {
        files.forEach((file) => uploadBlob(zone, file));
      } else {
        uploadBlob(zone, files[0]);
      }
      input.value = '';
    });
  });

  document.querySelectorAll('.file-pick').forEach((button) => {
    button.addEventListener('click', () => {
      const input = button.closest('.action-panel').querySelector('.paste-file');
      if (input) input.click();
    });
  });

  document.querySelectorAll('[data-copy-value]').forEach((button) => {
    button.addEventListener('click', async () => {
      const value = button.dataset.copyValue || '';
      if (!value) return;
      await navigator.clipboard.writeText(value);
      const oldText = button.textContent;
      button.textContent = 'kopiert';
      setTimeout(() => { button.textContent = oldText; }, 900);
    });
  });

  document.addEventListener('click', (event) => {
    const button = event.target && event.target.closest ? event.target.closest('[data-remove-page]') : null;
    if (!button) return;
    const form = button.closest('form');
    const input = form && form.querySelector('[data-pages-json]');
    const index = Number(button.dataset.removePage);
    const pages = queuedPages(input);
    if (!Number.isInteger(index) || index < 0 || index >= pages.length) return;
    pages.splice(index, 1);
    input.value = JSON.stringify(pages);
    renderQueuedPages(form);
    const zone = form && form.querySelector('.paste-zone[data-collect-pages="1"]');
    if (zone) {
      const label = opberichtZone(zone) ? 'OP-Bericht speichern und auslesen' : praeopZone(zone) ? 'Auslesen lassen' : ambulanzZone(zone) ? 'Ambulanzkartei speichern und auslesen' : histologyZone(zone) ? 'Histologie speichern und auslesen' : 'Patientenbrief auslesen';
      setState(zone, pages.length ? `${pages.length} Seite(n) bereit - dann ${label}` : 'keine Seite vorgemerkt', pages.length ? 'ok' : '');
    }
  });

  document.querySelectorAll('[data-pages-json]').forEach((input) => {
    renderQueuedPages(input.closest('form'));
  });

  document.querySelectorAll('[data-select-intervention]').forEach((link) => {
    link.addEventListener('click', () => {
      const value = link.dataset.selectIntervention || '';
      const href = link.getAttribute('href') || '#opberichte';
      const id = href.includes('#') ? href.split('#').pop() : '';
      const target = id ? document.getElementById(id) : document.getElementById('opberichte');
      const panel = target && (target.tagName === 'DETAILS' ? target : target.closest('details'));
      if (panel && panel.tagName === 'DETAILS') panel.open = true;
      const scope = target || panel || document;
      const selects = scope.querySelectorAll ? scope.querySelectorAll('select[name="eingriff_id"]') : [];
      selects.forEach((select) => {
        if (value) {
          select.value = value;
          select.dispatchEvent(new Event('change', { bubbles: true }));
        }
      });
      if (!selects.length && panel && panel !== scope) {
        panel.querySelectorAll('select[name="eingriff_id"]').forEach((select) => {
          if (value) {
            select.value = value;
            select.dispatchEvent(new Event('change', { bubbles: true }));
          }
        });
      }
    });
  });

  let opPreviewTimer = null;
  function setOpPreviewState(form, text, stateClass) {
    const state = form.querySelector('.op-preview-state');
    if (!state) return;
    state.textContent = text;
    state.classList.remove('ok', 'warn', 'bad');
    if (stateClass) state.classList.add(stateClass);
  }

  function fillOpReportFields(form, fields) {
    Object.entries(fields || {}).forEach(([name, value]) => {
      if (!value) return;
      const input = form.querySelector(`[name="${name}"]`);
      if (input && !input.value) {
        input.value = value;
      }
    });
  }

  async function previewOpReport(form) {
    const textarea = form.querySelector('[name="bericht_text"]');
    const text = textarea && textarea.value ? textarea.value.trim() : '';
    if (text.length < 20) {
      setOpPreviewState(form, 'Text einfügen, dann lese ich ihn vorab aus', '');
      return;
    }
    setOpPreviewState(form, 'Text wird ausgelesen...', 'warn');
    try {
      const response = await fetch('/opbericht-preview', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ text })
      });
      const result = await response.json();
      if (!response.ok || !result.ok) {
        throw new Error(result.error || 'Auslesen fehlgeschlagen');
      }
      fillOpReportFields(form, result.fields || {});
      const terms = result.terms && result.terms.length ? `: ${result.terms.join(', ')}` : '';
      setOpPreviewState(form, `Vorschläge übernommen${terms}`, 'ok');
    } catch (error) {
      setOpPreviewState(form, error.message || 'Auslesen fehlgeschlagen', 'bad');
    }
  }

  document.querySelectorAll('form.op-report-form').forEach((form) => {
    const textarea = form.querySelector('[name="bericht_text"]');
    const button = form.querySelector('[data-op-preview]');
    if (textarea) {
      textarea.addEventListener('paste', () => {
        window.clearTimeout(opPreviewTimer);
        opPreviewTimer = window.setTimeout(() => previewOpReport(form), 120);
      });
      textarea.addEventListener('input', () => {
        window.clearTimeout(opPreviewTimer);
        opPreviewTimer = window.setTimeout(() => previewOpReport(form), 700);
      });
    }
    if (button) {
      button.addEventListener('click', () => {
        const pagesInput = form.querySelector('[data-pages-json]');
        const pages = queuedPages(pagesInput);
        const textarea = form.querySelector('[name="bericht_text"]');
        const reportText = textarea && textarea.value ? textarea.value.trim() : '';
        if (pages.length && reportText.length < 20) {
          setOpPreviewState(form, `${pages.length} Seite(n) werden gespeichert und ausgelesen...`, 'warn');
          button.disabled = true;
          form.requestSubmit();
          return;
        }
        previewOpReport(form);
      });
    }
  });

  function openTargetDetails() {
    if (!window.location.hash) return;
    const id = decodeURIComponent(window.location.hash.slice(1));
    const target = document.getElementById(id);
    if (!target) return;
    const panels = [];
    if (target.tagName === 'DETAILS') panels.push(target);
    let panel = target.closest('details');
    while (panel) {
      panels.push(panel);
      panel = panel.parentElement ? panel.parentElement.closest('details') : null;
    }
    if (panels.length) {
      panels.reverse().forEach((item) => { item.open = true; });
      window.setTimeout(() => target.scrollIntoView({ block: 'start' }), 0);
    }
  }

  document.querySelectorAll('form.ambulanz-entry-review').forEach((form) => {
    form.addEventListener('submit', async (event) => {
      event.preventDefault();
      const submitter = event.submitter;
      if (!submitter) return;
      const originalText = submitter.textContent;
      const data = new URLSearchParams(new FormData(form));
      data.set(submitter.name, submitter.value);
      const buttons = Array.from(form.querySelectorAll('button'));
      buttons.forEach((button) => { button.disabled = true; });
      try {
        const response = await fetch(form.action, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/x-www-form-urlencoded;charset=UTF-8',
            'X-Requested-With': 'ambulanz-entry-review'
          },
          body: data.toString()
        });
        const result = await response.json();
        if (!response.ok || !result.ok) throw new Error('Speichern fehlgeschlagen');
        const item = form.closest('.timeline-item');
        const badge = item && item.querySelector('.entry-review-status');
        const labels = {
          fallbezogen: 'manuell: wichtig für diesen Fall',
          anderes_gelenk: 'manuell: anderes Gelenk/Thema',
          nicht_relevant: 'manuell: nicht relevant',
          offen: 'automatisch eingeordnet · noch prüfen'
        };
        if (badge) {
          badge.textContent = labels[result.status] || result.status;
          badge.classList.remove('ok', 'warn', 'danger');
          badge.classList.add(result.status === 'fallbezogen' ? 'ok' : result.status === 'nicht_relevant' ? 'danger' : 'warn');
        }
        const facts = item && item.querySelector('details.entry-facts');
        if (facts && result.status === 'fallbezogen') facts.open = true;
        submitter.textContent = 'gespeichert';
        window.setTimeout(() => { submitter.textContent = originalText; }, 700);
      } catch (error) {
        const badge = form.closest('.timeline-item')?.querySelector('.entry-review-status');
        if (badge) {
          badge.textContent = 'Speichern fehlgeschlagen';
          badge.classList.remove('ok', 'warn');
          badge.classList.add('danger');
        }
      } finally {
        buttons.forEach((button) => { button.disabled = false; });
      }
    });
  });

  document.querySelectorAll('form.ambulanz-entry-link').forEach((form) => {
    form.addEventListener('submit', async (event) => {
      event.preventDefault();
      const button = event.submitter;
      if (!button) return;
      const originalText = button.textContent;
      button.disabled = true;
      try {
        const response = await fetch(form.action, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/x-www-form-urlencoded;charset=UTF-8',
            'X-Requested-With': 'ambulanz-entry-link'
          },
          body: new URLSearchParams(new FormData(form)).toString()
        });
        const result = await response.json();
        if (!response.ok || !result.ok) throw new Error('Speichern fehlgeschlagen');
        const badge = form.querySelector('.entry-link-status');
        if (badge) {
          badge.textContent = result.eingriff_id
            ? `verknüpft mit Eingriff #${result.eingriff_id}`
            : 'Verknüpfung entfernt';
          badge.classList.remove('warn', 'danger');
          badge.classList.add(result.eingriff_id ? 'ok' : 'warn');
        }
        button.textContent = 'gespeichert';
        window.setTimeout(() => { button.textContent = originalText; }, 700);
      } catch (error) {
        const badge = form.querySelector('.entry-link-status');
        if (badge) {
          badge.textContent = 'Speichern fehlgeschlagen';
          badge.classList.remove('ok', 'warn');
          badge.classList.add('danger');
        }
      } finally {
        button.disabled = false;
      }
    });
  });

  document.querySelectorAll('form.ambulanz-primary-create').forEach((form) => {
    form.addEventListener('submit', async (event) => {
      event.preventDefault();
      const button = event.submitter;
      if (!button || button.disabled) return;
      const badge = form.querySelector('.primary-create-status');
      button.disabled = true;
      button.textContent = 'wird angelegt…';
      try {
        const response = await fetch(form.action, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/x-www-form-urlencoded;charset=UTF-8',
            'X-Requested-With': 'ambulanz-primary-create'
          },
          body: new URLSearchParams(new FormData(form)).toString()
        });
        const result = await response.json();
        if (!response.ok || !result.ok) throw new Error('Anlegen fehlgeschlagen');
        button.textContent = `Primäreingriff #${result.eingriff_id} angelegt`;
        if (badge) {
          badge.textContent = `Aufenthalt #${result.aufenthalt_id} · ${result.brief_count} Patientenbrief(e) verknüpft`;
          badge.classList.remove('info', 'warn', 'danger');
          badge.classList.add('ok');
        }
        const linkForm = form.parentElement && form.parentElement.querySelector('form.ambulanz-entry-link');
        const select = linkForm && linkForm.querySelector('[name="eingriff_id"]');
        if (select && !Array.from(select.options).some((option) => option.value === String(result.eingriff_id))) {
          select.add(new Option(`#${result.eingriff_id} · neu angelegte Primärimplantation`, String(result.eingriff_id), true, true));
        } else if (select) {
          select.value = String(result.eingriff_id);
        }
        const linkBadge = linkForm && linkForm.querySelector('.entry-link-status');
        if (linkBadge) {
          linkBadge.textContent = `verknüpft mit Eingriff #${result.eingriff_id}`;
          linkBadge.classList.remove('warn', 'danger');
          linkBadge.classList.add('ok');
        }
      } catch (error) {
        button.disabled = false;
        button.textContent = 'Primäreingriff anlegen';
        if (badge) {
          badge.textContent = 'Anlegen fehlgeschlagen';
          badge.classList.remove('info', 'ok', 'warn');
          badge.classList.add('danger');
        }
      }
    });
  });

  document.addEventListener('submit', (event) => {
    const form = event.target;
    if (!(form instanceof HTMLFormElement)) return;
    const method = (form.getAttribute('method') || 'get').toLowerCase();
    const action = new URL(form.getAttribute('action') || window.location.href, window.location.href);
    if (method === 'post' && action.origin === window.location.origin) {
      rememberScrollPosition(form);
    }
  }, true);

  window.addEventListener('hashchange', openTargetDetails);
  if (!restoreScrollPosition()) {
    openTargetDetails();
  }

  document.addEventListener('click', (event) => {
    const link = event.target && event.target.closest ? event.target.closest('.workflow-status-link') : null;
    if (link) event.stopPropagation();
  }, true);

	  document.addEventListener('paste', (event) => {
	    const target = event.target && event.target.nodeType === 1 ? event.target : document.activeElement;
	    const file = pickClipboardImage(event);
	    const textTarget = isTextEntryTarget(target) && !(target.closest && target.closest('.paste-zone'));
	    if (textTarget && !file) {
	      activeZone = null;
	      return;
	    }
	    const zone = nearestPasteZone(target) || (usablePasteZone(activeZone) ? activeZone : null);
	    if (!zone) return;
	    if (!file) {
	      if (textUploadZone(zone)) {
        const text = event.clipboardData && event.clipboardData.getData('text/plain');
        if (text && text.trim()) {
          event.preventDefault();
          if (appendTextToFormTextarea(zone, text)) {
            return;
          }
          uploadTextDocument(zone, text);
          return;
        }
      }
      setState(zone, textUploadZone(zone) ? 'Kein Screenshot/Text in der Zwischenablage' : 'Kein Screenshot in der Zwischenablage', 'bad');
      return;
    }
    event.preventDefault();
    uploadBlob(zone, file);
  });
})();
</script>
"""


def db_connect(db_path: Path) -> sqlite3.Connection:
    con = sqlite3.connect(db_path)
    con.row_factory = sqlite3.Row
    con.execute("PRAGMA foreign_keys = ON")
    migrate_episode_model(con)
    ensure_manual_register_support(con)
    ensure_review_table(con)
    ensure_review_app_indexes(con)
    con.execute(
        """CREATE TABLE IF NOT EXISTS tblFieberkurveAusleseStatus (
               FieberkurveID INTEGER PRIMARY KEY,
               TexteErledigt INTEGER NOT NULL DEFAULT 0,
               LokalErledigt INTEGER NOT NULL DEFAULT 0,
               BildKIErledigt INTEGER NOT NULL DEFAULT 0,
               UpdatedAt TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
               FOREIGN KEY (FieberkurveID) REFERENCES tblFieberkurve(FieberkurveID) ON DELETE CASCADE
           )"""
    )
    con.commit()
    return con


class ReviewApp(BaseHTTPRequestHandler):
    server_version = "PJIReview/0.1"

    @property
    def db_path(self) -> Path:
        return self.server.db_path  # type: ignore[attr-defined]

    def do_GET(self) -> None:
        parsed = urlparse(self.path)
        path = unquote(parsed.path)
        query = parse_qs(parsed.query)
        try:
            if path == "/":
                self.render_dateneingabe(query)
            elif path in {"/datenerhebung", "/dateneingabe"}:
                self.render_dateneingabe(query)
            elif path in {"/datenstand", "/quellen"}:
                self.render_sources()
            elif path == "/auswertung":
                self.render_auswertung(query)
            elif path == "/weiter":
                self.redirect_next_case(query)
            elif path == "/kollektiv":
                self.render_kollektiv(query)
            elif path == "/patienten":
                self.render_patienten(query)
            elif path.startswith("/fallakte/") and (
                path.endswith("/praeop-upload")
                or path.endswith("/praeop-clipboard")
                or path.endswith("/opbericht-clipboard")
                or path.endswith("/ambulanz-upload")
                or path.endswith("/ambulanz-clipboard")
                or path.endswith("/histo-upload")
                or path.endswith("/patientenbrief-upload")
                or path.endswith("/patientenbrief-clipboard")
            ):
                kollektiv_id = int(path.removeprefix("/fallakte/").split("/", 1)[0])
                if "praeop" in path:
                    target_page = "praeop"
                elif "opbericht" in path:
                    target_page = "opberichte"
                elif "ambulanz" in path:
                    target_page = "ambulanz"
                elif "histo" in path:
                    target_page = "histologie"
                else:
                    target_page = "eingriffe"
                self.redirect(f"/fallakte/{kollektiv_id}/{target_page}#aufenthalte")
            elif path.startswith("/fallakte/"):
                parts = [part for part in path.removeprefix("/fallakte/").split("/") if part]
                kollektiv_id = int(parts[0])
                page_name = parts[1] if len(parts) > 1 else "cockpit"
                self.render_fallakte(kollektiv_id, page_name, query)
            elif path == "/export/fieberkurven_kollektiv.csv":
                self.serve_kollektiv_csv(query)
            elif path == "/export/patienten_infektverdacht.csv":
                self.serve_patienten_csv(query)
            elif path.startswith("/review/") and path.endswith("/append-pages"):
                fever_id = int(path.removeprefix("/review/").removesuffix("/append-pages"))
                self.redirect(f"/review/{fever_id}")
            elif path.startswith("/review/") and any(
                path.endswith(suffix)
                for suffix in (
                    "/ocr-medications", "/source-medications", "/vision-run",
                    "/date-range", "/extraction-step",
                )
            ):
                fever_id = int(path.removeprefix("/review/").split("/", 1)[0])
                self.redirect(f"/review/{fever_id}#auswertung")
            elif path.startswith("/review/"):
                fever_id = int(path.removeprefix("/review/"))
                self.render_review(fever_id, query)
            elif path.startswith("/opbericht-file/"):
                report_id = int(path.removeprefix("/opbericht-file/"))
                self.serve_op_report_file(report_id)
            elif path.startswith("/praeop-file/"):
                praeop_id = int(path.removeprefix("/praeop-file/"))
                self.serve_praeop_file(praeop_id)
            elif path.startswith("/patientenbrief-file/"):
                letter_id = int(path.removeprefix("/patientenbrief-file/"))
                self.serve_patientenbrief_file(letter_id)
            elif path.startswith("/ambulanz-file/"):
                ambulanz_id = int(path.removeprefix("/ambulanz-file/"))
                self.serve_ambulanz_file(ambulanz_id)
            elif path.startswith("/image/"):
                page_id = int(path.removeprefix("/image/"))
                self.serve_image(page_id)
            else:
                self.send_error(HTTPStatus.NOT_FOUND)
        except (BrokenPipeError, ConnectionResetError):
            # The browser navigated away while a large patient page was still
            # being written.  There is no application error to report and a
            # second error response would only produce the misleading
            # "Error response" page/log entry.
            return
        except ValueError:
            self.send_error(HTTPStatus.BAD_REQUEST)
        except Exception as exc:
            self.send_error(HTTPStatus.INTERNAL_SERVER_ERROR, explain=str(exc))

