    def patienten_rows(
        self,
        con: sqlite3.Connection,
        query: dict[str, list[str]],
        *,
        limit: int | None,
    ) -> list[sqlite3.Row]:
        where_sql, params = self.kollektiv_where(query)
        limit_sql = "" if limit is None else f"LIMIT {int(limit)}"
        return con.execute(
            f"""
            WITH filtered AS (
                SELECT *
                FROM tblFieberkurveKollektiv
                WHERE {where_sql}
            ),
            grouped AS (
                SELECT
                    PatientID,
                    MAX(PatientenzahlSAP) AS PatientenzahlSAP,
                    MAX(PatientHash) AS PatientHash,
                    MIN(Prioritaet) AS HoechstePrioritaet,
                    COUNT(*) AS Kandidaten,
                    COUNT(DISTINCT GelenkFallID) AS GelenkFaelle,
                    COUNT(DISTINCT EpisodeID) AS Episoden,
                    COUNT(DISTINCT EingriffID) AS Eingriffe,
                    GROUP_CONCAT(DISTINCT TRIM(COALESCE(Gelenk, '') || ' ' || COALESCE(Seite, ''))) AS Gelenke,
                    GROUP_CONCAT(DISTINCT SAPFallnummer) AS SAPFallnummern,
                    MIN(OPDatum) AS ErsteOP,
                    MAX(OPDatum) AS LetzteOP,
                    MIN(ErstePositiveKultur) AS ErstePositiveKultur,
                    MAX(LetztePositiveKultur) AS LetztePositiveKultur,
                    SUM(CASE WHEN SAPScreenshotStatus = 'offen' THEN 1 ELSE 0 END) AS Offen,
                    SUM(CASE WHEN SAPScreenshotStatus = 'importiert' THEN 1 ELSE 0 END) AS Importiert,
                    SUM(CASE WHEN SAPScreenshotStatus = 'reviewt' THEN 1 ELSE 0 END) AS Reviewt,
                    SUM(CASE WHEN FieberkurveStatus IN ('vorhanden', 'reviewt') THEN 1 ELSE 0 END) AS FieberkurvenVorhanden,
                    GROUP_CONCAT(DISTINCT ErregerListe) AS ErregerListe,
                    GROUP_CONCAT(DISTINCT MaterialListe) AS MaterialListe
                FROM filtered
                GROUP BY PatientID
            )
            SELECT
                ROW_NUMBER() OVER (ORDER BY HoechstePrioritaet, ErsteOP IS NULL, ErsteOP, PatientID) AS LaufNr,
                *
            FROM grouped
            ORDER BY HoechstePrioritaet, ErsteOP IS NULL, ErsteOP, PatientID
            {limit_sql}
            """,
            params,
        ).fetchall()

