    def ambulanz_study_hints(self, fields: dict[str, object], report_text: object = "") -> list[str]:
        text = normalized_medication_text(
            report_text,
            fields.get("DiagnoseText"),
            fields.get("TherapieText"),
            fields.get("VerlaufText"),
            fields.get("AntibiotikaText"),
            fields.get("OPHinweisText"),
        )
        hints: list[str] = []
        rules = (
            (r"\b(infekt|infektion|fistel|sekretion|eiter|entzündungszeichen)\w*\b", "Infekt-/Wundhinweis"),
            (r"\b(pfannen|schaft|prothesen)?lockerung\w*\b", "Lockerung beschrieben"),
            (r"\b(inlayverschlei(?:ß|ss)|luxation|dezentrierung)\w*\b", "mechanisches Problem beschrieben"),
            (r"\b(schmerz|schmerzen|druckschmerz)\w*\b", "Schmerzen dokumentiert"),
            (r"\b(revision|wechsel[- ]?operation|pfannenwechsel|inlaywechsel|kopfwechsel)\w*\b", "Revision/Wechsel vorgesehen"),
            (r"\b(kontrolle|wiedervorstellung|termin)\w*\b", "Kontrolle/Wiedervorstellung"),
        )
        for pattern, label in rules:
            if re.search(pattern, text, re.IGNORECASE):
                hints.append(label)
        medications: list[str] = []
        for entry in load_lexicon():
            if any(term and candidate_pattern(term).search(text) for term in entry.terms):
                medications.append(f"{entry.name_norm} ({entry.klasse})" if entry.klasse else entry.name_norm)
        if medications:
            hints.append("Antibiotika: " + ", ".join(dict.fromkeys(medications)))
        return hints[:8]

    def ambulanz_display_fields(self, row: sqlite3.Row) -> dict[str, object]:
        fields: dict[str, object] = {}
        if row["ExtractedJSON"]:
            try:
                decoded = json.loads(row["ExtractedJSON"])
                if isinstance(decoded, dict):
                    fields.update(decoded)
            except (TypeError, json.JSONDecodeError):
                pass
        for column, key in [
            ("DokumentDatum", "DokumentDatum"),
            ("KontaktDatum", "KontaktDatum"),
            ("Arzt", "Arzt"),
            ("DiagnoseText", "DiagnoseText"),
            ("TherapieText", "TherapieText"),
            ("VerlaufText", "VerlaufText"),
            ("AntibiotikaText", "AntibiotikaText"),
            ("OPHinweisText", "OPHinweisText"),
            ("WiedervorstellungText", "WiedervorstellungText"),
        ]:
            if column in row.keys() and row[column]:
                fields[key] = row[column]
        bericht_text = row["BerichtText"] if "BerichtText" in row.keys() else ""
        # Existing automatic imports benefit from improved extraction rules
        # immediately.  Explicit user corrections always remain authoritative.
        if bericht_text and not fields.get("ManuellKorrigiert"):
            refreshed = self.extract_ambulanzkartei_fields_from_text(str(bericht_text))
            for key, value in refreshed.items():
                if value:
                    fields[key] = value
        if bericht_text and not fields.get("Zeitleiste"):
            timeline = self.ambulanz_timeline_from_text(str(bericht_text))
            if timeline:
                fields["Zeitleiste"] = timeline
                fields.setdefault("KontaktVon", timeline[0].get("Datum"))
                fields.setdefault("KontaktBis", timeline[-1].get("Datum"))
        for key, value in list(fields.items()):
            if isinstance(value, str):
                fields[key] = self.redact_patient_identifiers(value)
            elif isinstance(value, list):
                cleaned_entries = []
                for entry in value:
                    if isinstance(entry, dict):
                        cleaned_entries.append(
                            {
                                str(item_key): self.redact_patient_identifiers(str(item_value))
                                if isinstance(item_value, str)
                                else item_value
                                for item_key, item_value in entry.items()
                            }
                        )
                    else:
                        cleaned_entries.append(entry)
                fields[key] = cleaned_entries
        return fields

    def praeop_display_fields(self, row: sqlite3.Row) -> dict[str, object]:
        fields: dict[str, object] = {}
        if "ExtractedJSON" in row.keys() and row["ExtractedJSON"]:
            try:
                decoded = json.loads(row["ExtractedJSON"])
                if isinstance(decoded, dict):
                    fields.update(decoded)
            except (TypeError, json.JSONDecodeError):
                pass
        for column, key in [
            ("DokumentDatum", "DokumentDatum"),
            ("Aufnahme", "Aufnahme"),
            ("Entlassung", "Entlassung"),
            ("Fallnummer", "Fallnummer"),
            ("Diagnose", "Diagnose"),
            ("GeplanteTherapie", "GeplanteTherapie"),
            ("MedikationText", "MedikationText"),
            ("OrthopaedischeVoroperationen", "OrthopaedischeVoroperationen"),
            ("RelevanteVorerkrankungen", "RelevanteVorerkrankungen"),
            ("Allergien", "Allergien"),
            ("StatusText", "StatusText"),
        ]:
            if column in row.keys() and row[column]:
                fields[key] = row[column]
        # Re-run automatic extraction for older imports so parser improvements
        # become visible without another upload. Never overwrite a record that
        # a user has already corrected and saved manually.
        if row["BerichtText"] and not fields.get("ManuellKorrigiert"):
            refreshed = self.extract_praeop_anamnese_fields_from_text(row["BerichtText"])
            for key, value in refreshed.items():
                if value:
                    fields[key] = value
        return fields

