    def create_primary_intervention_from_ambulanz(self, kollektiv_id: int, form: dict[str, list[str]]) -> None:
        ambulanz_id = int_or_none(first(form.get("ambulanz_id")))
        raw_indexes = (first(form.get("entry_indexes")) or "").strip()
        entry_indexes = [int(value) for value in raw_indexes.split(",") if value.strip().isdigit()]
        if not ambulanz_id or not entry_indexes:
            self.send_error(HTTPStatus.BAD_REQUEST, explain="Zeitleisteneintrag fehlt")
            return
        with db_connect(self.db_path) as con:
            case = self.get_kollektiv_case(con, kollektiv_id)
            if not case:
                self.send_error(HTTPStatus.NOT_FOUND, explain="Fallakte nicht gefunden")
                return
            row = con.execute(
                "SELECT ExtractedJSON FROM tblAmbulanzKarteiDokument WHERE AmbulanzKarteiID = ? AND EpisodeID = ?",
                (ambulanz_id, case["EpisodeID"]),
            ).fetchone()
            if not row:
                self.send_error(HTTPStatus.NOT_FOUND, explain="Ambulanzkartei nicht gefunden")
                return
            try:
                extracted = json.loads(row["ExtractedJSON"] or "{}")
            except (TypeError, json.JSONDecodeError):
                extracted = {}
            entries = extracted.get("Zeitleiste") if isinstance(extracted, dict) else None
            if not isinstance(entries, list) or any(
                index < 0 or index >= len(entries) or not isinstance(entries[index], dict)
                for index in entry_indexes
            ):
                self.send_error(HTTPStatus.BAD_REQUEST, explain="Zeitleisteneintrag wurde nicht gefunden")
                return
            entry = entries[entry_indexes[0]]
            facts = self.ambulanz_entry_facts(entry)
            op_date = iso_date_or_blank(next((value for label, value in facts if label == "OP-Datum"), ""))
            procedure = next((value for label, value in facts if label == "Eingriff"), "").strip()
            diagnosis = next((value for label, value in facts if label == "Diagnose im Beleg"), "").strip()
            procedure_lower = procedure.lower()
            looks_primary = bool(
                re.search(r"\bimplantation\b.{0,80}\b(?:tep|prothese)\b", procedure_lower)
                and not re.search(r"\b(reimplant|explant|wechsel|revision|reoperation)\w*\b", procedure_lower)
            )
            if not op_date or not procedure or not looks_primary:
                self.send_error(HTTPStatus.BAD_REQUEST, explain="Der Eintrag ist nicht eindeutig als Primärimplantation erkennbar")
                return
            intervention = self.fetch_case_intervention_by_date(con, case, op_date)
            if intervention:
                intervention_id = int(intervention["EingriffID"])
                stay_id = int(intervention["AufenthaltID"])
            else:
                stay = self.stay_matching_op_date(con, case, op_date)
                if stay:
                    stay_id = int(stay["AufenthaltID"])
                else:
                    fallnummer = str(case["SAPFallnummer"] or case["MedizinischerFall"] or "").strip() or None
                    cur = con.execute(
                        """
                        INSERT INTO tblAufenthalt (
                            GelenkFallID, EpisodeID, Fallnummer, MedizinischerFall, Aufnahme, Quelle
                        ) VALUES (?, ?, ?, ?, ?, 'Ambulanzkartei_Auto')
                        """,
                        (case["GelenkFallID"], case["EpisodeID"], fallnummer, fallnummer, op_date),
                    )
                    stay_id = int(cur.lastrowid)
                comment_parts = ["Automatisch aus geprüftem Ambulanzkartei-Eintrag angelegt; bitte kontrollieren."]
                if diagnosis:
                    comment_parts.append(f"Diagnose im Beleg: {diagnosis}")
                cur = con.execute(
                    """
                    INSERT INTO tblEingriff (
                        AufenthaltID, OPDatum, EingriffsartID, EingriffsartTextQuelle,
                        Quelle, Kommentar, KeinOrthodokErwartet
                    ) VALUES (?, ?, 1, ?, 'Ambulanzkartei_Auto', ?, 1)
                    """,
                    (stay_id, op_date, procedure, " ".join(comment_parts)),
                )
                intervention_id = int(cur.lastrowid)
            for entry_index in entry_indexes:
                entries[entry_index]["ReviewEingriffID"] = intervention_id
            con.execute(
                "UPDATE tblAmbulanzKarteiDokument SET ExtractedJSON = ?, UpdatedAt = CURRENT_TIMESTAMP WHERE AmbulanzKarteiID = ?",
                (json.dumps(extracted, ensure_ascii=False), ambulanz_id),
            )
            con.execute(
                """
                UPDATE tblGelenkFall
                SET PrimaerimplantationDatum = COALESCE(PrimaerimplantationDatum, ?),
                    PrimaerimplantationKommentar = COALESCE(
                        NULLIF(PrimaerimplantationKommentar, ''),
                        'Aus Ambulanzkartei abgeleitet; automatisch angelegt und zu prüfen'
                    ),
                    UpdatedAt = CURRENT_TIMESTAMP
                WHERE GelenkFallID = ?
                """,
                (op_date, case["GelenkFallID"]),
            )
            brief_count = int(con.execute(
                "SELECT COUNT(*) FROM tblPatientenbriefDokument WHERE AufenthaltID = ?",
                (stay_id,),
            ).fetchone()[0])
            con.commit()
        if self.headers.get("X-Requested-With") == "ambulanz-primary-create":
            self.send_json({
                "ok": True,
                "eingriff_id": intervention_id,
                "aufenthalt_id": stay_id,
                "brief_count": brief_count,
            })
            return
        self.redirect(f"/fallakte/{kollektiv_id}/eingriffe#intervention-{intervention_id}")

    def update_ambulanzkartei(self, kollektiv_id: int, form: dict[str, list[str]]) -> None:
        ambulanz_id = int_or_none(first(form.get("ambulanz_id")))
        if not ambulanz_id:
            self.send_error(HTTPStatus.BAD_REQUEST, explain="Ambulanzkartei fehlt")
            return
        status = (first(form.get("review_status")) or "offen").strip()
        if status not in {"offen", "unklar", "bearbeitet", "bestaetigt"}:
            status = "offen"
        with db_connect(self.db_path) as con:
            case = self.get_kollektiv_case(con, kollektiv_id)
            if not case:
                self.send_error(HTTPStatus.NOT_FOUND, explain="Fallakte nicht gefunden")
                return
            current = con.execute(
                """
                SELECT *
                FROM tblAmbulanzKarteiDokument
                WHERE AmbulanzKarteiID = ? AND EpisodeID = ?
                """,
                (ambulanz_id, case["EpisodeID"]),
            ).fetchone()
            if not current:
                self.send_error(HTTPStatus.NOT_FOUND, explain="Ambulanzkartei nicht gefunden")
                return
            requested_intervention_id = int_or_none(first(form.get("eingriff_id")))
            intervention = self.validated_case_intervention(con, case, requested_intervention_id) if requested_intervention_id else None
            document_type = (first(form.get("dokument_typ")) or current["DokumentTyp"] or "ambulanzbrief").strip()
            if document_type not in {"ambulanzkartei", "ambulanzbrief"}:
                document_type = "ambulanzbrief"
            if document_type == "ambulanzkartei":
                duplicate_chart = con.execute(
                    """SELECT d.AmbulanzKarteiID
                       FROM tblAmbulanzKarteiDokument d
                       JOIN tblEpisode ep ON ep.EpisodeID = d.EpisodeID
                       JOIN tblGelenkFall g ON g.GelenkFallID = ep.GelenkFallID
                       WHERE g.PatientID = ? AND d.DokumentTyp = 'ambulanzkartei'
                         AND d.AmbulanzKarteiID <> ?
                         AND COALESCE(d.ReviewStatus, 'offen') <> 'geloescht' LIMIT 1""",
                    (case["PatientID"], ambulanz_id),
                ).fetchone()
                if duplicate_chart:
                    self.send_error(HTTPStatus.BAD_REQUEST, explain="Für diesen Patienten ist bereits eine Ambulanzkartei vorhanden")
                    return
                intervention = None
            field_map = {
                "DokumentDatum": (first(form.get("dokument_datum")) or "").strip(),
                "KontaktDatum": (first(form.get("kontakt_datum")) or "").strip(),
                "Arzt": (first(form.get("arzt")) or "").strip(),
                "DiagnoseText": (first(form.get("diagnose_text")) or "").strip(),
                "TherapieText": (first(form.get("therapie_text")) or "").strip(),
                "VerlaufText": (first(form.get("verlauf_text")) or "").strip(),
                "AntibiotikaText": (first(form.get("antibiotika_text")) or "").strip(),
                "OPHinweisText": (first(form.get("op_hinweis_text")) or "").strip(),
                "WiedervorstellungText": (first(form.get("wiedervorstellung_text")) or "").strip(),
            }
            extracted = {}
            if current["ExtractedJSON"]:
                try:
                    decoded = json.loads(current["ExtractedJSON"])
                    if isinstance(decoded, dict):
                        extracted.update(decoded)
                except (TypeError, json.JSONDecodeError):
                    extracted = {}
            for key, value in field_map.items():
                if value:
                    extracted[key] = value
                else:
                    extracted.pop(key, None)
            extracted["ManuellKorrigiert"] = True
            con.execute(
                """
                UPDATE tblAmbulanzKarteiDokument
                SET AufenthaltID = ?,
                    EingriffID = ?,
                    DokumentDatum = ?,
                    KontaktDatum = ?,
                    Arzt = ?,
                    DiagnoseText = ?,
                    TherapieText = ?,
                    VerlaufText = ?,
                    AntibiotikaText = ?,
                    OPHinweisText = ?,
                    WiedervorstellungText = ?,
                    BerichtText = ?,
                    ExtractedJSON = ?,
                    ReviewStatus = ?,
                    Kommentar = ?,
                    DokumentTyp = ?,
                    UpdatedAt = CURRENT_TIMESTAMP
                WHERE AmbulanzKarteiID = ? AND EpisodeID = ?
                """,
                (
                    intervention["AufenthaltID"] if intervention else current["AufenthaltID"],
                    intervention["EingriffID"] if intervention else None,
                    field_map["DokumentDatum"] or None,
                    field_map["KontaktDatum"] or None,
                    field_map["Arzt"] or None,
                    field_map["DiagnoseText"] or None,
                    field_map["TherapieText"] or None,
                    field_map["VerlaufText"] or None,
                    field_map["AntibiotikaText"] or None,
                    field_map["OPHinweisText"] or None,
                    field_map["WiedervorstellungText"] or None,
                    (first(form.get("bericht_text")) or "").strip() or None,
                    json.dumps(extracted, ensure_ascii=False),
                    status,
                    (first(form.get("kommentar")) or "").strip() or None,
                    document_type,
                    ambulanz_id,
                    case["EpisodeID"],
                ),
            )
            if intervention:
                self.update_intervention_reoperation_reason_from_text(
                    con,
                    int(intervention["EingriffID"]),
                    source="Ambulanzkartei",
                    texts=(
                        field_map["DiagnoseText"],
                        field_map["TherapieText"],
                        field_map["VerlaufText"],
                        field_map["AntibiotikaText"],
                        field_map["OPHinweisText"],
                        first(form.get("bericht_text")),
                    ),
                )
            con.commit()
        self.redirect(f"/fallakte/{kollektiv_id}/ambulanz#ambulanz-{ambulanz_id}")

