    def register_source_file(self, con: sqlite3.Connection, *, source_system: str, path: Path, comment: str | None = None) -> int:
        cur = con.execute(
            """
            INSERT INTO tblSourceFile (
                SourceSystem, OriginalPath, FileName, FileHashSHA256, Comment
            )
            VALUES (?, ?, ?, ?, ?)
            """,
            (source_system, str(path), path.name, self.file_sha256(path), comment),
        )
        return int(cur.lastrowid)

    def parse_report_date(self, value: str) -> str | None:
        value = value.strip()
        if not value:
            return None
        try:
            if re.match(r"^\d{4}-\d{1,2}-\d{1,2}$", value):
                year, month, day = (int(part) for part in value.split("-"))
                parsed = date(year, month, day)
                return parsed.isoformat()
            normalized = value.replace("-", ".").replace("/", ".")
            for fmt in ("%d.%m.%Y", "%d.%m.%y"):
                try:
                    parsed = datetime.strptime(normalized, fmt).date()
                    if 1990 <= parsed.year <= date.today().year + 2:
                        return parsed.isoformat()
                except ValueError:
                    pass
        except ValueError:
            return None
        return None

    def report_lines(self, text: str) -> list[str]:
        lines = []
        for line in text.splitlines():
            clean_line = re.sub(r"\s+", " ", line).strip(" :-\t")
            if clean_line:
                lines.append(clean_line)
        return lines

    def redact_patient_identifiers(self, text: str) -> str:
        if not text:
            return ""
        redacted = text
        name_patterns = (
            r"\bPatient(?:in)?\s*[:.]?\s*([A-ZÄÖÜ][A-Za-zÄÖÜäöüß'´`-]{2,})\s+([A-ZÄÖÜ][A-Za-zÄÖÜäöüß'´`-]{2,})",
            r"\b([A-ZÄÖÜ][A-Za-zÄÖÜäöüß'´`-]{2,})\s+([A-ZÄÖÜ][A-Za-zÄÖÜäöüß'´`-]{2,})\s*,\s*geb\.?",
        )
        names: set[str] = set()
        for pattern in name_patterns:
            for match in re.finditer(pattern, redacted):
                parts = [part.strip() for part in match.groups() if part.strip()]
                if len(parts) >= 2:
                    names.add(" ".join(parts[:2]))
                    names.add(", ".join(parts[:2]))
                    names.add(" ".join(reversed(parts[:2])))
                    names.add(", ".join(reversed(parts[:2])))
        for name in sorted(names, key=len, reverse=True):
            if len(name) >= 6:
                redacted = re.sub(re.escape(name), "[Name entfernt]", redacted)
        redacted = re.sub(
            r"\bgeb\.?\s*(?:am)?\s*\d{1,2}[./-]\d{1,2}[./-]\d{2,4}\b",
            "geb. [entfernt]",
            redacted,
            flags=re.IGNORECASE,
        )
        redacted = re.sub(
            r"\bgeb\.?\s*(?:am)?\s*\d{4}-\d{1,2}-\d{1,2}\b",
            "geb. [entfernt]",
            redacted,
            flags=re.IGNORECASE,
        )
        redacted = re.sub(
            r"\bA-\d{4}\s+[^\n,;]{3,80}(?:,\s*[^\n,;]{3,80})?",
            "[Adresse entfernt]",
            redacted,
        )
        return redacted

    def ambulanz_timeline_from_text(self, text: str) -> list[dict[str, str]]:
        lines = text.splitlines()
        entries: list[dict[str, str]] = []
        current: dict[str, object] | None = None
        entry_rx = re.compile(
            r"^\s*(\d{4}-\d{1,2}-\d{1,2}|\d{1,2}[./]\d{1,2}[./]\d{2,4})\s*,?\s*(?:\d{1,2}:\d{2})?\s*,?\s*([^:\n]{0,90}):?\s*(.*)$",
            re.IGNORECASE,
        )
        for raw_line in lines:
            line = re.sub(r"\s+", " ", raw_line).strip()
            if not line:
                continue
            match = entry_rx.match(line)
            if match:
                if current:
                    entries.append(
                        {
                            "Datum": str(current.get("Datum") or ""),
                            "Arzt": short_list(" ".join(current.get("Arzt") or []), max_chars=90),
                            "Text": short_list(" ".join(current.get("Text") or []), max_chars=360),
                        }
                    )
                current = {
                    "Datum": self.parse_report_date(match.group(1)) or match.group(1),
                    "Arzt": [match.group(2).strip(" ,-")] if match.group(2).strip(" ,-") else [],
                    "Text": [match.group(3).strip()] if match.group(3).strip() else [],
                }
                continue
            if current:
                current.setdefault("Text", []).append(line)
        if current:
            entries.append(
                {
                    "Datum": str(current.get("Datum") or ""),
                    "Arzt": short_list(" ".join(current.get("Arzt") or []), max_chars=90),
                    "Text": short_list(" ".join(current.get("Text") or []), max_chars=360),
                }
            )
        deduped: list[dict[str, str]] = []
        seen: set[tuple[str, str]] = set()
        for entry in entries:
            key = (entry.get("Datum", ""), entry.get("Text", "")[:80])
            if not entry.get("Datum") or key in seen:
                continue
            seen.add(key)
            deduped.append(entry)
        return deduped[:20]

    def line_is_identifier_context(self, line: str) -> bool:
        haystack = line.lower()
        return any(
            marker in haystack
            for marker in (
                "patient",
                "geb.",
                "geboren",
                "geburtsdatum",
                "adresse",
                "aufnahme",
                "entlassung",
                "fallnummer",
                "versicher",
            )
        )

    def date_from_labeled_lines(self, lines: list[str], labels: tuple[str, ...]) -> str | None:
        for index, line in enumerate(lines):
            haystack = line.lower()
            if not any(label in haystack for label in labels):
                continue
            for candidate_line in lines[index : index + 2]:
                match = DATE_PATTERN.search(candidate_line)
                if match:
                    parsed = self.parse_report_date(match.group(1))
                    if parsed:
                        return parsed
        return None

    def first_report_date(self, lines: list[str], filename: str | None = None) -> str | None:
        for source in [*lines, filename or ""]:
            if not source or self.line_is_identifier_context(source):
                continue
            match = DATE_PATTERN.search(source)
            if match:
                parsed = self.parse_report_date(match.group(1))
                if parsed:
                    return parsed
        return None

    def matched_report_terms(self, text: str, patterns: tuple[tuple[str, str], ...]) -> list[str]:
        terms: list[str] = []
        for label, pattern in patterns:
            if re.search(pattern, text, re.IGNORECASE | re.DOTALL) and label not in terms:
                terms.append(label)
        return terms

    def tail_after_label(self, line: str, labels: tuple[str, ...], *, max_chars: int = 140) -> str | None:
        for label in labels:
            match = re.search(rf"{re.escape(label)}\s*[:\-/]?\s*(.+)$", line, re.IGNORECASE)
            if match:
                tail = re.sub(r"\s+", " ", match.group(1)).strip(" :-")
                if 2 <= len(tail) <= max_chars:
                    return tail
        return None

    def best_procedure_line(self, lines: list[str]) -> str | None:
        labels = (
            "durchgeführte operation",
            "durchgefuehrte operation",
            "operation",
            "op:",
            "eingriff",
            "prozedur",
            "therapie",
            "operationsbericht",
        )
        candidates: list[tuple[int, str]] = []
        for line in lines:
            if len(line) < 8 or len(line) > 260 or self.line_is_identifier_context(line):
                continue
            haystack = line.lower()
            score = 0
            if any(label in haystack for label in labels):
                score += 3
            if any(re.search(pattern, haystack, re.IGNORECASE) for _, pattern in PROCEDURE_PATTERNS):
                score += 4
            if "diagnose" in haystack or "indikation" in haystack:
                score += 1
            if score:
                cleaned = re.sub(
                    r"^(?:durchgef(?:ü|ue)hrte operation|operation|op|eingriff|prozedur|therapie)\s*[:\-/]?\s*",
                    "",
                    line,
                    flags=re.IGNORECASE,
                ).strip(" :-")
                candidates.append((score, cleaned))
        if not candidates:
            return None
        candidates.sort(key=lambda item: (-item[0], len(item[1])))
        return short_list(candidates[0][1], max_chars=180)

    def labeled_or_terms(
        self,
        lines: list[str],
        full_text: str,
        labels: tuple[str, ...],
        patterns: tuple[tuple[str, str], ...],
    ) -> str | None:
        for line in lines:
            tail = self.tail_after_label(line, labels)
            if tail:
                return tail
        terms = self.matched_report_terms(full_text, patterns)
        return "; ".join(terms[:6]) if terms else None

    def section_after_heading(
        self,
        lines: list[str],
        headings: tuple[str, ...],
        stop_headings: tuple[str, ...],
        *,
        max_lines: int = 8,
    ) -> str | None:
        start = None
        for index, line in enumerate(lines):
            normalized = line.lower().strip(" :-")
            if any(heading in normalized for heading in headings):
                start = index
                break
        if start is None:
            return None
        chunks: list[str] = []
        first_tail = None
        for heading in sorted(headings, key=len, reverse=True):
            match = re.match(rf"^\s*{re.escape(heading)}\s*:\s*(.+)$", lines[start], re.IGNORECASE)
            if match:
                first_tail = short_list(re.sub(r"\s+", " ", match.group(1)).strip(" :-"), max_chars=240)
                break
        if first_tail:
            chunks.append(first_tail)
        for line in lines[start + 1 : start + 1 + max_lines]:
            normalized = line.lower().strip(" :-")
            if any(re.match(rf"^{re.escape(stop)}(?:\b|[:/\-])", normalized) for stop in stop_headings):
                break
            if line:
                chunks.append(line)
        return short_list("; ".join(chunks), max_chars=600) if chunks else None

    def extract_praeop_anamnese_fields_from_text(self, text: str) -> dict[str, object]:
        lines = self.report_lines(text)
        full_text = "\n".join(lines)
        one_line = re.sub(r"\s+", " ", full_text)
        raw_one_line = re.sub(r"\s+", " ", text).strip()

        def raw_section(start_patterns: tuple[str, ...], stop_patterns: tuple[str, ...], max_chars: int = 1200) -> str | None:
            start_match = None
            for pattern in start_patterns:
                candidate = re.search(pattern, raw_one_line, re.IGNORECASE)
                if candidate and (start_match is None or candidate.start() < start_match.start()):
                    start_match = candidate
            if not start_match:
                return None
            end = min(len(raw_one_line), start_match.end() + max_chars)
            for pattern in stop_patterns:
                candidate = re.search(pattern, raw_one_line[start_match.end():], re.IGNORECASE)
                if candidate:
                    end = min(end, start_match.end() + candidate.start())
            value = raw_one_line[start_match.end():end].strip(" :-;,.")
            return re.sub(r"\s+", " ", value) or None
        stop_headings = (
            "anamnese",
            "diagnose",
            "therapie",
            "definitiv geplante",
            "weitere orthopädische",
            "weitere orthopaedische",
            "sonstige relevante",
            "allergien",
            "status",
            "befund",
            "procedere",
        )
        anamnese_stop_headings = stop_headings + (
            "orthop.",
            "orthop",
            "vorop.",
            "vorop",
            "fk",
            "jk",
            "status praesens",
            "status präsens",
            "status prasens",
            "status lokalis",
            "diagnose",
            "therapie",
        )
        dokument_datum = self.date_from_labeled_lines(lines, ("anamnese/status", "anamnese", "vom")) or self.first_report_date(lines)
        date_rx = r"(\d{1,2}[./-]\d{1,2}[./-]\d{2,4}|\d{4}-\d{1,2}-\d{1,2})"
        stay_match = re.search(
            rf"station[aä]rer\s+aufenthalt\s+von\s+{date_rx}\s+bis\s+{date_rx}",
            one_line,
            re.IGNORECASE,
        )
        aufnahme = entlassung = None
        if stay_match:
            aufnahme = self.parse_report_date(stay_match.group(1))
            entlassung = self.parse_report_date(stay_match.group(2))
        fall_match = re.search(r"\bfall(?:nr\.?|nummer)?\s*[:.]?\s*([0-9]{5,})", one_line, re.IGNORECASE)
        weight_match = re.search(r"\b(\d{2,3})\s*kg\b", one_line, re.IGNORECASE)
        height_match = re.search(r"\b(\d{3})\s*cm\b", one_line, re.IGNORECASE)
        anamnese = self.section_after_heading(lines, ("anamnese",), anamnese_stop_headings, max_lines=14)
        diagnosis = self.section_after_heading(lines, ("diagnose",), stop_headings, max_lines=3)
        therapy = self.section_after_heading(
            lines,
            ("therapie", "definitiv geplante op/therapie", "definitiv geplante op", "geplante op"),
            stop_headings,
            max_lines=4,
        )
        ortho_preops = self.section_after_heading(
            lines,
            (
                "weitere orthopädische voroperationen",
                "weitere orthopaedische voroperationen",
                "orthop. vorop",
                "orthop vorop",
                "orthopädische voroperationen",
                "vorop.",
                "vorop",
            ),
            ("fk", "jk", "status", "diagnose", "therapie", "allergie", "befund"),
            max_lines=8,
        )
        other_preops = self.section_after_heading(
            lines,
            ("fk", "sonstige relevante voroperationen", "sonstige voroperationen"),
            ("jk", "status", "diagnose", "therapie", "allergie", "befund"),
            max_lines=6,
        )
        current_complaints = self.section_after_heading(
            lines,
            ("jk", "jetzige krankengeschichte", "jetzige beschwerden"),
            ("status", "diagnose", "therapie", "allergie", "befund"),
            max_lines=14,
        )
        comorbidities = self.section_after_heading(
            lines,
            ("sonstige relevante vorerkrankungen", "vorkrankheiten", "relevante vorerkrankungen"),
            stop_headings,
            max_lines=8,
        )
        allergies = self.section_after_heading(
            lines,
            ("allergien/unvertr./risikofakt.", "allergien", "allergie"),
            stop_headings,
            max_lines=5,
        )
        status_praesens = self.section_after_heading(
            lines,
            ("status praesens", "status präsens", "status prasens"),
            ("allergie", "status lokalis", "diagnose", "therapie", "procedere", "befund"),
            max_lines=5,
        )
        status_lokalis = self.section_after_heading(
            lines,
            ("status lokalis", "lokalis"),
            ("diagnose", "therapie", "procedere", "befund"),
            max_lines=12,
        )
        status_text = "; ".join(part for part in [status_praesens, status_lokalis] if part) or None

        medication = raw_section(
            (r"\bmed\.?\s*:", r"\bmedikation\s*:"),
            (
                r"\borth\.?\s*(?:ve\s*/\s*op|vor[- ]?op|erkrankungen)\s*:",
                r"\borthop(?:ä|ae)dische\b",
                r"\bund\s+vor[- ]?op\s*:",
                r"\bfeiop\s*:",
                r"\bsonstige\s*:",
                r"\b(?:re\.?\s*h[aä]nd\w*|nik\.?|alk\.?|harn|stuhl|sa|fk|je|jk|stat(?:us)?)\b",
            ),
            700,
        )
        raw_ortho_preops = raw_section(
            (r"\borthop(?:ä|ae)dische\s+erkrankungen\s+und\s+vor[- ]?op\s*:", r"\bund\s+vor[- ]?op\s*:"),
            (r"\bsonstige\s*:", r"\b(?:jk|status)\s*:"),
            1300,
        )
        raw_other = raw_section(
            (r"\bsonstige\s*:",),
            (r"\b(?:jk|status)\s*:", r"\bdiagnose\s*:"),
            1200,
        )
        raw_complaints = raw_section(
            (r"\bjk\s*:", r"\bjetzige\s+(?:krankengeschichte|beschwerden)\s*:"),
            (r"\bstatus\b", r"\bdiagnose\s*:"),
            1800,
        )
        raw_status = raw_section(
            (r"\bstatus\s*:?​?",),
            (r"\bdiagnose\s*:", r"\btherapie\s*:"),
            1800,
        )
        raw_allergies = raw_section(
            (r"\ballergie\s*:", r"\ballergien\s*:"),
            (r"\bsa\s*:", r"\bmed\.?\s*:", r"\borthop(?:ä|ae)dische\b"),
            600,
        )
        raw_diagnosis = raw_section((r"\bdiagnose\s*:",), (r"\btherapie\s*:",), 700)
        raw_therapy = raw_section(
            (r"\btherapie\s*:",),
            (r"\bprocedere\s*:", r"\bdatum\s*:", r"\bunterschrift\b"),
            1000,
        )

        # Präop forms are often OCR'd word by word. Work on the flattened text
        # and use the printed field labels as hard boundaries so content does
        # not spill into the next form field.
        raw_anamnese = raw_section(
            (r"\banamnese\b",),
            (
                r"\bmed(?:ikation)?\.?\s*:",
                r"\borth\.?\s*(?:ve|vor[- ]?op|erkrankungen)\b",
                r"\borthop\.?\s*(?:ve|vor[- ]?op|erkrankungen)\b",
                r"\b(?:fk|feiop|je|jk)\s*:",
            ),
            1800,
        )
        raw_ortho_preops = raw_section(
            (
                r"\borth\.?\s*ve\s*/\s*op\s*:",
                r"\borthop(?:ä|ae)?dische\s+erkrankungen\s+und\s+vor[- ]?op\s*:",
                r"\borthop(?:ä|ae)?dische\s+vor[- ]?op(?:erationen)?\s*:",
            ),
            (r"\bfeiop\s*:", r"\bsonstige\s*:", r"\b(?:je|jk)\s*:"),
            1400,
        ) or raw_ortho_preops
        raw_other = raw_section(
            (r"\bfeiop\s*:", r"\bsonstige\s+(?:relevante\s+)?vor[- ]?op(?:erationen)?\s*:"),
            (r"\b(?:je|jk)\s*:", r"\bstatus\b", r"\bdiagnose\s*:"),
            1200,
        ) or raw_other
        raw_complaints = raw_section(
            (r"\b(?:je|jk)\s*:", r"\bjetzige\s+(?:krankengeschichte|beschwerden)\s*:"),
            (r"\bstatus(?:\s+pr(?:ä|ae|a)sens)?\s*:?",),
            1800,
        ) or raw_complaints
        raw_status_praesens = raw_section(
            (r"\bstatus\s+pr(?:ä|ae|a)sens\s*:",),
            (r"\bstatus\s+loc(?:alis)?\s*:", r"\bdiagnose\s*:"),
            1000,
        )
        raw_status_lokalis = raw_section(
            (r"\bstatus\s+loc(?:alis)?\s*:", r"\bstatus\s+lokalis\s*:"),
            (r"\bdiagnose\s*:", r"\btherapie\s*:"),
            1800,
        )
        raw_allergies = raw_section(
            (r"\ballergien?\s*:",),
            (
                r"\b(?:re\.?\s*h[aä]nd|h[aä]nder|nik\.?|alk\.?|harn\s*/?\s*stu|sa)\s*[:.]?",
                r"\bstat(?:us|\.)?\s*(?:loc|lok)",
                r"\bmed(?:ikation)?\.?\s*:",
                r"\borth\.",
            ),
            350,
        ) or raw_allergies

        def split_other_history(value: str | None) -> tuple[str | None, str | None]:
            if not value:
                return None, None
            # Many forms put operations and medical diagnoses on one OCR line.
            # Once a clear disease-only part begins, keep it out of the OP field.
            disease_start = re.search(
                r"\b(?:art\.?\s*hyperton|diabet|pulmonalembolie|thrombose|copd|asthma|gastritis)\w*",
                value,
                re.IGNORECASE,
            )
            trailing_diseases = None
            if disease_start:
                trailing_diseases = value[disease_start.start():].strip(" ,;.")
                value = value[:disease_start.start()].strip(" ,;.")
            chunks = [chunk.strip(" ,;.") for chunk in re.split(r"\s*[,;]\s*", value) if chunk.strip(" ,;.")]
            op_chunks: list[str] = []
            disease_chunks: list[str] = []
            op_rx = re.compile(r"\b(?:op|operiert|ektomie|resektion|arthroskop|tep|prothese|osteosynthese)\b", re.I)
            disease_rx = re.compile(r"\b(?:hyperton|diabet|embolie|thromb|karzin|ca\b|gastritis|copd|asthma|insuffizienz)\w*", re.I)
            for chunk in chunks:
                if disease_rx.search(chunk) and not op_rx.search(chunk):
                    disease_chunks.append(chunk)
                else:
                    op_chunks.append(chunk)
            if trailing_diseases:
                disease_chunks.append(trailing_diseases)
            return ("; ".join(op_chunks) or None, "; ".join(disease_chunks) or None)

        parsed_other_ops, parsed_other_diseases = split_other_history(raw_other)
        if raw_ortho_preops:
            ortho_preops = raw_ortho_preops
        if raw_other:
            other_preops = parsed_other_ops
            if parsed_other_diseases:
                comorbidities = parsed_other_diseases
        if other_preops and re.search(r"\bsiehe\s+anamnesebogen\b", other_preops, re.IGNORECASE):
            if not re.search(
                r"\b(?:tep|ask|arthroskop|ektomie|resektion|prothese|osteosynthese|strumektomie|hysterektomie|che|ae|te)\b",
                other_preops,
                re.IGNORECASE,
            ):
                other_preops = None
        if raw_complaints:
            current_complaints = raw_complaints
        if raw_anamnese:
            anamnese = raw_anamnese
        if raw_status_praesens or raw_status_lokalis:
            # Allergy information has its own field and is removed from the
            # general status to avoid duplication.
            clean_praesens = raw_status_praesens
            if clean_praesens:
                clean_praesens = re.sub(
                    r"\ballergien?\s*:.*?(?=\bharn\s*/?\s*stu|$)",
                    "",
                    clean_praesens,
                    flags=re.IGNORECASE,
                ).strip(" ,;.")
                clean_praesens = re.sub(
                    r"\bmed(?:ikation)?\.?\s*:.*?(?=\bnik\.?\b|\balk\.?\b|\bharn\b|$)",
                    "",
                    clean_praesens,
                    flags=re.IGNORECASE,
                ).strip(" ,;.")
            status_text = "; ".join(part for part in (clean_praesens, raw_status_lokalis) if part) or None
        elif raw_status:
            status_text = raw_status
        if raw_allergies:
            allergies = raw_allergies
        if raw_diagnosis:
            diagnosis = raw_diagnosis
        if raw_therapy:
            therapy = raw_therapy
        return {
            "DokumentDatum": dokument_datum,
            "Aufnahme": aufnahme,
            "Entlassung": entlassung,
            "Fallnummer": fall_match.group(1) if fall_match else None,
            "AnamneseText": anamnese,
            "Diagnose": diagnosis,
            "GeplanteTherapie": therapy,
            "MedikationText": medication,
            "OrthopaedischeVoroperationen": ortho_preops,
            "SonstigeVoroperationen": other_preops,
            "BeschwerdenText": current_complaints,
            "RelevanteVorerkrankungen": comorbidities,
            "Allergien": allergies,
            "StatusText": status_text,
            "GewichtKg": weight_match.group(1) if weight_match else None,
            "GroesseCm": height_match.group(1) if height_match else None,
            "TextZeichen": len(text),
            "AutomatischExtrahiert": any([dokument_datum, aufnahme, entlassung, fall_match, anamnese, diagnosis, therapy, ortho_preops, other_preops, current_complaints, comorbidities, allergies, status_text]),
        }

    def extract_patientenbrief_fields_from_text(self, text: str) -> dict[str, object]:
        lines = self.report_lines(text)
        full_text = "\n".join(lines)
        one_line = re.sub(r"\s+", " ", full_text)
        stay_text = re.sub(r"(?<=\d)\s*([./-])\s*(?=\d)", r"\1", one_line)
        date_rx = r"(\d{1,2}[./-]\d{1,2}[./-]\d{2,4}|\d{4}-\d{1,2}-\d{1,2})"
        # OCR occasionally drops the leading "b" in "bis" (for example
        # "Aufenthalt seit 2007-03-26 is 2007-04-06"). Between two dates this
        # remains an unambiguous range marker and should not lose the stay.
        range_sep = r"(?:\s+b?is\s+|\s*b?is\s*|\s+[–—-]\s+)"
        stop_headings = (
            "diagnosen",
            "diagnose",
            "durchgeführte maßnahmen",
            "durchgefuehrte massnahmen",
            "durchgeführte massnahmen",
            "empfohlene medikation",
            "medikation",
            "weitere maßnahmen",
            "weitere massnahmen",
            "verlauf",
            "labor befunde",
            "erhobene befunde",
            "befundtext",
            "therapie",
        )
        dokument_datum = self.date_from_labeled_lines(
            lines,
            ("patientenbrief", "entlassungsbrief", "arztbrief", "bericht", "vom"),
        ) or self.first_report_date(lines)
        aufnahme = entlassung = None
        stay_patterns = (
            rf"station(?:[aä]|ae)r(?:er|en)?(?:\s+\w+){{0,3}}\s+(?:seit|von|v\.?)?\s*{date_rx}{range_sep}{date_rx}",
            rf"\baufenthalt\b.{{0,40}}?{date_rx}{range_sep}{date_rx}",
            rf"\b(?:seit|von|v\.?)\s*{date_rx}{range_sep}{date_rx}\b",
        )
        for pattern in stay_patterns:
            stay_match = re.search(pattern, stay_text, re.IGNORECASE)
            if stay_match:
                aufnahme = self.parse_report_date(stay_match.group(1))
                entlassung = self.parse_report_date(stay_match.group(2))
                break
        fall_match = re.search(r"\bfall(?:nr\.?|nummer)?\s*[:.]?\s*([0-9]{5,})", one_line, re.IGNORECASE)
        diagnoses = self.section_after_heading(lines, ("diagnosen", "diagnose"), stop_headings, max_lines=8)
        massnahmen = self.section_after_heading(
            lines,
            ("durchgeführte maßnahmen", "durchgefuehrte massnahmen", "durchgeführte massnahmen"),
            stop_headings,
            max_lines=10,
        )
        weitere_massnahmen = self.section_after_heading(
            lines,
            ("weitere maßnahmen", "weitere massnahmen"),
            stop_headings,
            max_lines=30,
        )
        medication = self.section_after_heading(
            lines,
            ("empfohlene medikation", "medikation"),
            stop_headings,
            max_lines=24,
        )
        verlauf = self.section_after_heading(lines, ("verlauf",), stop_headings, max_lines=18)
        labor = self.section_after_heading(lines, ("labor befunde", "laborbefunde", "labordaten"), stop_headings, max_lines=30)
        konsil_stop_headings = tuple(stop for stop in stop_headings if stop not in {"diagnosen", "diagnose"})
        konsil = self.section_after_heading(lines, ("erhobene befunde", "int. konsil", "internistisches konsil", "konsil"), konsil_stop_headings, max_lines=20)
        operation_lines = []
        for index, line in enumerate(lines):
            if re.search(r"\b(?:operation|op)\s*:", line, re.IGNORECASE):
                operation_line = re.sub(r"\s+", " ", line).strip()
                after_label = re.sub(r"^.*?\b(?:operation|op)\s*:\s*", "", operation_line, flags=re.IGNORECASE)
                if re.fullmatch(r"(?:\d{1,2}[./-]\d{1,2}[./-]\d{2,4}|\d{4}-\d{1,2}-\d{1,2})[;,.]?", after_label):
                    for continuation in lines[index + 1 : index + 4]:
                        continuation_clean = re.sub(r"\s+", " ", continuation).strip()
                        if not continuation_clean:
                            continue
                        continuation_lower = continuation_clean.lower().strip(" :-")
                        if any(
                            re.match(rf"^{re.escape(heading)}(?:\b|[:/\-])", continuation_lower)
                            for heading in stop_headings
                        ):
                            break
                        if re.search(
                            r"\b(implantation|reimplantation|explantation|wechsel|revision|debridement|dair|arthroskop|operation)\w*\b",
                            continuation_clean,
                            re.IGNORECASE,
                        ):
                            operation_line = f"{operation_line}; {continuation_clean}"
                        break
                operation_lines.append(operation_line)
        operation_text = short_list("; ".join(operation_lines), max_chars=600) or self.best_procedure_line(lines)
        med_rows = []
        in_medication = False
        for line in lines:
            normalized = line.lower().strip(" :-")
            if any(heading in normalized for heading in ("empfohlene medikation", "medikation")):
                in_medication = True
                continue
            if in_medication and any(re.match(rf"^{re.escape(stop)}(?:\b|[:/\-])", normalized) for stop in stop_headings if stop not in {"medikation", "empfohlene medikation"}):
                break
            if in_medication and re.search(r"\b\d+(?:[.,]\d+)?\s*(?:mg|g|ml|ie|iu|µg|mcg)?\b", line, re.IGNORECASE):
                med_rows.append(short_list(line, max_chars=160))
                if len(med_rows) >= 20:
                    break
        antibiotic_rows: list[dict[str, object]] = []
        for entry in load_lexicon():
            matched_term = None
            matched_index = None
            for index, line in enumerate(lines):
                for term in entry.terms:
                    if term and candidate_pattern(term).search(line):
                        matched_term = term
                        matched_index = index
                        break
                if matched_term:
                    break
            if matched_term is None or matched_index is None:
                continue
            context = " ".join(lines[matched_index : matched_index + 3])
            context = short_list(context, max_chars=420)
            term_pattern = re.escape(matched_term)
            dose_match = re.search(
                rf"\b{term_pattern}\b\s*(\d+(?:[.,]\d+)?)\s*(mg|g|µg|mcg)",
                context,
                re.IGNORECASE,
            )
            schedule_source = context[dose_match.end() : dose_match.end() + 60] if dose_match else context
            schedule_match = re.search(
                r"\b(\d+\s*(?:x\s*\d+|[-–]\s*\d+\s*[-–]\s*\d+(?:\s*[-–]\s*\d+)?))\b",
                schedule_source,
                re.IGNORECASE,
            )
            duration_match = re.search(
                r"\b(?:für|ueber|über)\s+(mindestens\s+)?(\d+)\s*(tag(?:e|en)?|woche(?:n)?|monat(?:e|en)?)\b",
                context,
                re.IGNORECASE,
            )
            route_match = re.search(r"\b(i\.?v\.?|p\.?o\.?|oral(?:e|en|er)?)\b", context, re.IGNORECASE)
            antibiotic_rows.append(
                {
                    "Name": entry.name_norm,
                    "ATC": entry.atc,
                    "Klasse": entry.klasse,
                    "ErkanntAls": matched_term,
                    "Dosis": f"{dose_match.group(1)} {dose_match.group(2)}" if dose_match else None,
                    "Schema": re.sub(r"\s+", "", schedule_match.group(1)).replace("–", "-") if schedule_match else None,
                    "Applikation": route_match.group(1) if route_match else None,
                    "Dauer": (
                        f"{'mindestens ' if duration_match.group(1) else ''}{duration_match.group(2)} {duration_match.group(3)}"
                        if duration_match
                        else None
                    ),
                    "Kontext": context,
                }
            )
        if not medication and antibiotic_rows:
            medication_parts = []
            for row in antibiotic_rows:
                name = str(row.get("ErkanntAls") or row.get("Name") or "Antibiotikum")
                details = [str(row[key]) for key in ("Dosis", "Schema", "Applikation", "Dauer") if row.get(key)]
                medication_parts.append(" ".join([name, *details]))
            medication = "; ".join(medication_parts)
        lab_rows = []
        current_lab_date = None
        lab_name_rx = r"(CRP|WBC|Leuko(?:zyten)?|HGB|Hb|Kreatinin|Kalium|Natrium|PCT|IL-6|BSG\s*1h|BSG\s*2h)"
        for line in lines:
            date_match = re.search(rf"Labordaten\s*,?\s*{date_rx}", line, re.IGNORECASE)
            if date_match:
                current_lab_date = self.parse_report_date(date_match.group(1))
                continue
            lab_match = re.search(rf"^{lab_name_rx}\s+\*?\s*([<>]?\s*\d+(?:[.,]\d+)?)\s*([A-Za-zµ/%]+/[A-Za-z0-9]+|[A-Za-zµ/%]+)?", line, re.IGNORECASE)
            if lab_match:
                lab_rows.append(
                    {
                        "Datum": current_lab_date,
                        "Parameter": lab_match.group(1),
                        "Wert": lab_match.group(2).replace(" ", ""),
                        "Einheit": lab_match.group(3) or None,
                    }
                )
        return {
            "DokumentDatum": dokument_datum,
            "Aufnahme": aufnahme,
            "Entlassung": entlassung,
            "Fallnummer": fall_match.group(1) if fall_match else None,
            "DiagnosenText": diagnoses,
            "MassnahmenText": massnahmen,
            "WeitereMassnahmenText": weitere_massnahmen,
            "OperationenText": operation_text,
            "MedikationText": medication,
            "VerlaufText": verlauf,
            "LaborText": labor,
            "KonsilText": konsil,
            "MedikationListe": med_rows,
            "AntibiotikaListe": antibiotic_rows,
            "Laborwerte": lab_rows,
            "TextZeichen": len(text),
            "AutomatischExtrahiert": any([dokument_datum, aufnahme, entlassung, fall_match, diagnoses, massnahmen, weitere_massnahmen, operation_text, medication, verlauf, labor, konsil, med_rows, antibiotic_rows, lab_rows]),
        }

    def extract_ambulanzkartei_fields_from_text(self, text: str) -> dict[str, object]:
        lines = self.report_lines(text)
        full_text = "\n".join(lines)
        one_line = re.sub(r"\s+", " ", full_text)
        stop_headings = (
            "diagnose",
            "leistungen",
            "operation",
            "therapie",
            "verlauf",
            "procedere",
            "kontrolle",
            "wiedervorstellung",
            "medikation",
            "antibiose",
            "antibiotikum",
        )

        dokument_datum = self.date_from_labeled_lines(lines, ("ambulanzkartei", "ambulanz", "wien", "vom")) or self.first_report_date(lines)
        kontakt_datum = None
        arzt = None
        entry_match = None
        for entry_pattern in (
            r"\b(\d{4}-\d{1,2}-\d{1,2}|\d{1,2}[./]\d{1,2}[./]\d{2,4})\s*,\s*\d{1,2}:\d{2}\s*,\s*([^:\n]{2,90}):",
            r"\b(\d{4}-\d{1,2}-\d{1,2}|\d{1,2}[./]\d{1,2}[./]\d{2,4})\s*,\s*([^:\n]{2,90}):",
        ):
            entry_match = re.search(entry_pattern, text, re.IGNORECASE)
            if entry_match:
                break
        if entry_match:
            kontakt_datum = self.parse_report_date(entry_match.group(1))
            arzt = short_list(entry_match.group(2).strip(" ,-"), max_chars=90)
        kontakt_datum = kontakt_datum or self.date_from_labeled_lines(lines, ("kontakt", "kontrolle", "ambulanz")) or dokument_datum

        # A patient chart is one longitudinal document. Split its dated author
        # headers into reviewable visits instead of treating every visit as a
        # separate chart/document.
        timeline_entries: list[dict[str, str]] = []
        visit_header = re.compile(
            r"(?m)^\s*(?P<date>\d{4}-\d{1,2}-\d{1,2}|\d{1,2}[./]\d{1,2}[./]\d{2,4})"
            r"\s*,\s*(?:(?P<time>\d{1,2}:\d{2})\s*,\s*)?(?P<doctor>[^:\n]{2,90})\s*:\s*"
        )
        visit_matches = list(visit_header.finditer(text))
        for index, match in enumerate(visit_matches):
            end = visit_matches[index + 1].start() if index + 1 < len(visit_matches) else len(text)
            visit_text = re.sub(r"\s+", " ", text[match.end():end]).strip(" -;\n")
            parsed_date = self.parse_report_date(match.group("date")) or match.group("date")
            timeline_entries.append(
                {
                    "Datum": parsed_date,
                    "Uhrzeit": str(match.group("time") or ""),
                    "Arzt": short_list(match.group("doctor").strip(" ,-"), max_chars=90),
                    "Text": short_list(visit_text, max_chars=1600),
                }
            )
        timeline_dates = [entry["Datum"] for entry in timeline_entries if entry.get("Datum")]

        diagnosis = self.section_after_heading(
            lines,
            ("diagnose", "station - diagnose", "diagnosen"),
            stop_headings,
            max_lines=5,
        )
        therapy = self.section_after_heading(
            lines,
            ("therapie", "procedere", "definitiv geplante op/therapie", "geplante therapie"),
            stop_headings,
            max_lines=8,
        )
        verlauf = self.section_after_heading(
            lines,
            ("verlauf", "beurteilung", "befund", "status"),
            stop_headings,
            max_lines=12,
        )

        def matching_lines(pattern: str, *, max_lines: int = 6) -> str | None:
            found: list[str] = []
            for line in lines:
                if re.search(pattern, line, re.IGNORECASE):
                    clean_line = short_list(line, max_chars=220)
                    if clean_line not in found:
                        found.append(clean_line)
                    if len(found) >= max_lines:
                        break
            return "; ".join(found) if found else None

        op_hint = matching_lines(
            r"\b(operation|op\b|leistungen|h-?tep|k-?tep|inlay|kopf|schaft|pfanne|wechsel|reposition|luxation|revision|punktion|fistel|debridement)\b",
            max_lines=8,
        )
        antibiotics = matching_lines(
            r"\b(antibiotikum|antibiose|antiinfektiv|i\.?\s*v\.?|p\.?\s*o\.?|abgesetzt|cef|cefurox|xim|xef|vancomycin|rifampicin|cipro|clinda|dalacin|augmentin|unasyn|tazobac|fosfomycin|linezolid)\b",
            max_lines=8,
        )
        follow_up = matching_lines(
            r"\b(kontrolle|wiedervorstellung|wieder vorstellen|bei bedarf|termin|vorstellung)\b",
            max_lines=6,
        )
        if not diagnosis:
            diagnosis_match = re.search(r"(?:diagnose|station\s*-\s*diagnose)\s*[:\-]\s*(.{5,240})", one_line, re.IGNORECASE)
            diagnosis = short_list(diagnosis_match.group(1), max_chars=240) if diagnosis_match else None
        if not therapy:
            therapy_match = re.search(r"(?:operation|therapie|leistungen)\s*[:\-]\s*(.{5,240})", one_line, re.IGNORECASE)
            therapy = short_list(therapy_match.group(1), max_chars=240) if therapy_match else None

        return {
            "DokumentDatum": dokument_datum,
            "KontaktDatum": kontakt_datum,
            "Arzt": arzt,
            "DiagnoseText": diagnosis,
            "TherapieText": therapy,
            "VerlaufText": verlauf,
            "AntibiotikaText": antibiotics,
            "OPHinweisText": op_hint,
            "WiedervorstellungText": follow_up,
            "Zeitleiste": timeline_entries,
            "KontaktVon": min(timeline_dates) if timeline_dates else kontakt_datum,
            "KontaktBis": max(timeline_dates) if timeline_dates else kontakt_datum,
            "TextZeichen": len(text),
            "AutomatischExtrahiert": any([dokument_datum, kontakt_datum, arzt, diagnosis, therapy, verlauf, antibiotics, op_hint, follow_up]),
        }

    def extract_op_report_fields_from_text(self, text: str, filename: str | None = None) -> dict[str, object]:
        lines = self.report_lines(text)
        full_text = "\n".join(lines)

        def labeled_value(*labels: str) -> str | None:
            label_pattern = "|".join(re.escape(label) for label in labels)
            for index, line in enumerate(lines):
                match = re.match(rf"^(?:{label_pattern})(?:\s*:|\s*$)[ \t]*(.*)$", line, re.IGNORECASE)
                if not match:
                    continue
                value = match.group(1).strip(" :-")
                if value:
                    return value
                if index + 1 < len(lines):
                    return lines[index + 1].strip(" :-") or None
            return None

        def section_value(start_labels: tuple[str, ...], stop_labels: tuple[str, ...]) -> str | None:
            start_pattern = "|".join(re.escape(label) for label in start_labels)
            stop_pattern = "|".join(re.escape(label) for label in stop_labels)
            for index, line in enumerate(lines):
                match = re.match(rf"^(?:{start_pattern})(?:\s*:|\s*$)[ \t]*(.*)$", line, re.IGNORECASE)
                if not match:
                    continue
                parts = [match.group(1).strip(" :-")]
                for following in lines[index + 1:]:
                    if re.match(rf"^(?:{stop_pattern})(?:\s*:|\s*$)", following, re.IGNORECASE):
                        break
                    parts.append(following.strip())
                value = " ".join(part for part in parts if part).strip()
                return short_list(value, max_chars=700) if value else None
            return None

        procedure_terms = self.matched_report_terms(full_text, PROCEDURE_PATTERNS)
        operation_section = section_value(
            ("operation", "eingriff"),
            ("team 1", "team", "operateure", "operateur", "op-assistent", "anästhesist", "anaesthesist", "instrum", "instrumentation", "op-bericht"),
        )
        procedure_line = operation_section or self.best_procedure_line(lines)
        if procedure_line and procedure_terms:
            summary = procedure_line
            for term in procedure_terms:
                if term.lower() not in summary.lower():
                    summary = f"{summary}; {term}"
                    if len(summary) > 180:
                        break
        else:
            summary = procedure_line or "; ".join(procedure_terms[:6])
        op_date = self.date_from_labeled_lines(lines, OP_DATE_LABELS) or self.first_report_date(lines, filename)
        document_date = self.date_from_labeled_lines(lines, DOCUMENT_DATE_LABELS) or op_date
        access = self.labeled_or_terms(
            lines,
            full_text,
            ("zugang", "schnittführung", "schnittfuehrung", "operationszugang"),
            ACCESS_PATTERNS,
        )
        probes = self.labeled_or_terms(
            lines,
            full_text,
            ("proben", "probe", "material", "mikrobiologie", "bakteriologie"),
            PROBE_PATTERNS,
        )
        implant = self.labeled_or_terms(
            lines,
            full_text,
            ("implantat", "implantate", "prothese", "komponenten"),
            IMPLANT_PATTERNS,
        )
        diagnosis = section_value(
            ("diagnose", "indikation"),
            ("operation", "eingriff", "team 1", "team", "operateure", "operateur", "op-bericht"),
        )
        operateur = labeled_value("operateure", "operateur")
        op_assistent = labeled_value("op-assistent", "op assistent", "assistenz", "assistent")
        legholder = labeled_value("legholder", "leg holder")
        anaesthesist = labeled_value(
            "anästhesist", "anaesthesist", "andsthesict", "andsthesist", "anästhesict", "anaesthesict"
        )
        instrumentation = labeled_value("instrum.", "instrum", "instrumentation")
        lagerung_terms = []
        for pattern, label in [
            (r"\brückenlage\b", "Rückenlage"),
            (r"\bseitenlage\b", "Seitenlage"),
            (r"\bbauchlage\b", "Bauchlage"),
            (r"\bintubationsnarkose\b", "Intubationsnarkose"),
            (r"\bspinalan(?:ä|ae)sthesie\b", "Spinalanästhesie"),
        ]:
            if re.search(pattern, full_text, re.IGNORECASE):
                lagerung_terms.append(label)
        lagerung_narkose = "; ".join(lagerung_terms) or None

        access_match = re.search(
            r"\b((?:midvastus|medialer\s+parapatellarer|lateraler\s+parapatellarer|transglutealer|anterolateraler|posterolateraler)[- ]zugang)\b",
            full_text,
            re.IGNORECASE,
        )
        if access_match:
            access = access_match.group(1)

        sample_block = re.search(
            r"\bgewebeproben?\b(.{0,500}?\bsonikation\s+geschickt\b)",
            full_text,
            re.IGNORECASE | re.DOTALL,
        )
        if sample_block:
            probes = re.sub(r"\s+", " ", sample_block.group(0)).strip(" -;,.\n")
        else:
            sample_sentences = []
            for sentence in re.split(r"(?<=[.!?])\s+|\n+", full_text):
                if re.search(r"\b(?:gewebeproben?|punktat|abstrich|sonikation|bakteriologie|gewebebakt)\b", sentence, re.IGNORECASE):
                    cleaned = sentence.strip(" -;,.\n")
                    if cleaned and cleaned not in sample_sentences:
                        sample_sentences.append(cleaned)
            probes = "; ".join(sample_sentences[:4]) or None

        if operation_section and re.search(r"\b(?:implant|prothese|stem|inlay|augmentation|komponente)\w*\b", operation_section, re.IGNORECASE):
            implant = operation_section
        return {
            "OPDatum": op_date,
            "DokumentDatum": document_date,
            "EingriffZusammenfassung": summary or None,
            "DiagnoseText": diagnosis,
            "Operateur": operateur,
            "OPAssistent": op_assistent,
            "Legholder": legholder,
            "Anaesthesist": anaesthesist,
            "Instrumentation": instrumentation,
            "LagerungNarkose": lagerung_narkose,
            "Zugang": access,
            "ProbenText": probes,
            "ImplantatText": implant,
            "GefundeneBegriffe": procedure_terms,
            "TextZeichen": len(text),
        }

    def read_text_file_fallback(self, path: Path) -> str:
        for encoding in ("utf-8", "latin-1", "cp1252"):
            try:
                return path.read_text(encoding=encoding)
            except UnicodeDecodeError:
                continue
        return path.read_text(errors="ignore")

    def extract_pdf_text_for_op_report(self, path: Path) -> str:
        if PdfReader is None:
            return ""
        try:
            reader = PdfReader(str(path))
            return "\n".join(page.extract_text() or "" for page in reader.pages).strip()
        except Exception:
            return ""

    def ocr_text_for_op_report(self, path: Path) -> tuple[str, str]:
        work_dir = OP_REPORT_DIR / "_ocr" / re.sub(r"[^A-Za-z0-9_.-]+", "_", path.stem)[:80]
        try:
            if path.suffix.lower() == ".pdf":
                if not BUNDLED_PDFTOPPM.exists():
                    return "", "ocr_unavailable_pdftoppm"
                pages = page_paths(path, work_dir, BUNDLED_PDFTOPPM)
            else:
                pages = [path]
        except Exception as exc:
            return "", f"ocr_render_failed: {exc}"

        page_texts = []
        statuses = []
        for page in pages[:8]:
            best_text = ""
            best_status = "ocr_unavailable"
            for language in ("deu+eng", "deu", "eng"):
                for psm in (6, 11):
                    text, status = run_tesseract(page, language, psm=psm, tesseract_path=None)
                    statuses.append(status)
                    if status == "ocr_finished" and len(text.strip()) > len(best_text.strip()):
                        best_text = text
                        best_status = status
                if best_status == "ocr_finished" and best_text.strip():
                    break
            if best_text.strip():
                page_texts.append(best_text.strip())
        if page_texts:
            return "\n\n".join(page_texts), "ocr_finished"
        return "", statuses[-1] if statuses else "ocr_unavailable"

    def extract_op_report_text(self, path: Path | None) -> tuple[str, str]:
        if path is None:
            return "", "manual_only"
        suffix = path.suffix.lower()
        if suffix == ".txt":
            return self.read_text_file_fallback(path), "text_file"
        if suffix == ".pdf":
            text = self.extract_pdf_text_for_op_report(path)
            if len(text.strip()) >= 80:
                return text, "pdf_text"
            ocr_text, status = self.ocr_text_for_op_report(path)
            return ocr_text, status
        if suffix in {".png", ".jpg", ".jpeg", ".tif", ".tiff"}:
            return self.ocr_text_for_op_report(path)
        return "", "unsupported"

    def auto_extract_op_report_values(self, target: Path | None, manual_text: str) -> dict[str, object]:
        file_text, extraction_status = self.extract_op_report_text(target)
        combined = "\n\n".join(part for part in [manual_text, file_text] if part.strip())
        if not combined.strip():
            return {"Extraktionsstatus": extraction_status, "AutomatischExtrahiert": False}
        fields = self.extract_op_report_fields_from_text(combined, target.name if target else None)
        fields["Extraktionsstatus"] = extraction_status
        fields["AutomatischExtrahiert"] = any(
            fields.get(key)
            for key in ("OPDatum", "DokumentDatum", "DiagnoseText", "EingriffZusammenfassung", "Operateur", "OPAssistent", "Anaesthesist", "Instrumentation", "Zugang", "ProbenText", "ImplantatText")
        )
        fields["RohtextGespeichert"] = bool(manual_text.strip())
        return fields

    def preview_op_report_text(self) -> None:
        length = int(self.headers.get("content-length", "0"))
        if length > 3 * 1024 * 1024:
            self.send_json({"ok": False, "error": "Text zu lang"}, status=HTTPStatus.BAD_REQUEST)
            return
        try:
            payload = json.loads(self.rfile.read(length).decode("utf-8"))
        except json.JSONDecodeError:
            self.send_json({"ok": False, "error": "Ungültige Anfrage"}, status=HTTPStatus.BAD_REQUEST)
            return
        text = str(payload.get("text") or "")
        fields = self.extract_op_report_fields_from_text(text, str(payload.get("filename") or "") or None)
        self.send_json(
            {
                "ok": True,
                "fields": {
                    "op_datum": fields.get("OPDatum") or "",
                    "dokument_datum": fields.get("DokumentDatum") or "",
                    "eingriff_zusammenfassung": fields.get("EingriffZusammenfassung") or "",
                    "diagnose_text": fields.get("DiagnoseText") or "",
                    "operateur": fields.get("Operateur") or "",
                    "op_assistent": fields.get("OPAssistent") or "",
                    "legholder": fields.get("Legholder") or "",
                    "anaesthesist": fields.get("Anaesthesist") or "",
                    "instrumentation": fields.get("Instrumentation") or "",
                    "lagerung_narkose": fields.get("LagerungNarkose") or "",
                    "zugang": fields.get("Zugang") or "",
                    "proben_text": fields.get("ProbenText") or "",
                    "implantat_text": fields.get("ImplantatText") or "",
                },
                "terms": fields.get("GefundeneBegriffe") or [],
            }
        )

    def save_op_report_upload_file(self, file_item: cgi.FieldStorage) -> Path:
        filename = Path(file_item.filename).name
        suffix = Path(filename).suffix.lower()
        if suffix not in {".pdf", ".png", ".jpg", ".jpeg", ".tif", ".tiff", ".txt"}:
            raise ValueError("Nur PDF-, Bild- oder Textdateien werden akzeptiert")
        OP_REPORT_DIR.mkdir(parents=True, exist_ok=True)
        target = self.unique_op_report_path(filename)
        with target.open("wb") as f:
            while True:
                chunk = file_item.file.read(1024 * 1024)
                if not chunk:
                    break
                f.write(chunk)
        return target

    def save_op_report_embedded_pages(self, pages_json: str | None, *, filename_prefix: str) -> list[Path]:
        if not pages_json or not pages_json.strip() or pages_json.strip() == "[]":
            return []
        try:
            pages = json.loads(pages_json)
        except json.JSONDecodeError as exc:
            raise ValueError("Vorgemerkte OP-Bericht-Seiten konnten nicht gelesen werden") from exc
        if not isinstance(pages, list):
            raise ValueError("Vorgemerkte OP-Bericht-Seiten sind ungültig")
        if len(pages) > 20:
            raise ValueError("Maximal 20 Seiten pro OP-Bericht einfügen")
        suffix_by_mime = {
            "image/png": ".png", "image/jpeg": ".jpg", "image/jpg": ".jpg",
            "image/tiff": ".tiff", "application/pdf": ".pdf", "text/plain": ".txt",
        }
        OP_REPORT_DIR.mkdir(parents=True, exist_ok=True)
        saved_paths: list[Path] = []
        for index, page in enumerate(pages, start=1):
            if not isinstance(page, dict):
                raise ValueError("Eine vorgemerkte OP-Bericht-Seite ist ungültig")
            data_url = str(page.get("dataUrl") or page.get("image_data") or "")
            match = re.match(r"^data:(image/(?:png|jpeg|jpg|tiff)|application/pdf|text/plain);base64,(.+)$", data_url, re.DOTALL)
            if not match:
                raise ValueError("Nur Bild, PDF oder Text wird unterstützt")
            try:
                upload_bytes = base64.b64decode(match.group(2), validate=True)
            except ValueError as exc:
                raise ValueError("Dateidaten einer OP-Bericht-Seite sind ungültig") from exc
            if not upload_bytes:
                raise ValueError("Leere OP-Bericht-Seite")
            raw_filename = Path(str(page.get("filename") or f"{filename_prefix}_Seite{index}")).name
            suffix = Path(raw_filename).suffix.lower()
            if suffix not in {".pdf", ".png", ".jpg", ".jpeg", ".tif", ".tiff", ".txt"}:
                suffix = suffix_by_mime.get(match.group(1), ".png")
            stem = Path(raw_filename).stem or f"{filename_prefix}_Seite{index}"
            target = self.unique_op_report_path(f"{safe_filename_part(stem, 'OPBericht')}_S{index:02d}{suffix}")
            target.write_bytes(upload_bytes)
            saved_paths.append(target)
        return saved_paths

    def create_op_report_document(
        self,
        con: sqlite3.Connection,
        case: sqlite3.Row,
        *,
        intervention_id: int | None,
        target: Path | None,
        additional_targets: list[Path] | None = None,
        values: dict[str, str],
    ) -> int:
        targets = [target] if target is not None else []
        targets.extend(additional_targets or [])
        clean_values = {
            key: (values.get(key) or "").strip()
            for key in (
                "eingriff_zusammenfassung",
                "diagnose_text",
                "operateur",
                "op_assistent",
                "legholder",
                "anaesthesist",
                "instrumentation",
                "lagerung_narkose",
                "zugang",
                "proben_text",
                "implantat_text",
                "bericht_text",
                "kommentar",
                "op_datum",
                "dokument_datum",
            )
        }
        page_texts = []
        for index, document_path in enumerate(targets, start=1):
            page_text, _ = self.extract_op_report_text(document_path)
            if page_text.strip():
                page_texts.append(f"--- Seite {index}: {document_path.name} ---\n{page_text.strip()}")
        combined_text = "\n\n".join(part for part in [clean_values["bericht_text"], *page_texts] if part.strip())
        clean_values["bericht_text"] = combined_text
        auto_values = self.auto_extract_op_report_values(None, combined_text)
        clean_values["op_datum"] = clean_values["op_datum"] or str(auto_values.get("OPDatum") or "")
        clean_values["dokument_datum"] = clean_values["dokument_datum"] or str(auto_values.get("DokumentDatum") or "")
        clean_values["eingriff_zusammenfassung"] = clean_values["eingriff_zusammenfassung"] or str(auto_values.get("EingriffZusammenfassung") or "")
        clean_values["diagnose_text"] = clean_values["diagnose_text"] or str(auto_values.get("DiagnoseText") or "")
        clean_values["operateur"] = clean_values["operateur"] or str(auto_values.get("Operateur") or "")
        clean_values["op_assistent"] = clean_values["op_assistent"] or str(auto_values.get("OPAssistent") or "")
        clean_values["legholder"] = clean_values["legholder"] or str(auto_values.get("Legholder") or "")
        clean_values["anaesthesist"] = clean_values["anaesthesist"] or str(auto_values.get("Anaesthesist") or "")
        clean_values["instrumentation"] = clean_values["instrumentation"] or str(auto_values.get("Instrumentation") or "")
        clean_values["lagerung_narkose"] = clean_values["lagerung_narkose"] or str(auto_values.get("LagerungNarkose") or "")
        clean_values["zugang"] = clean_values["zugang"] or str(auto_values.get("Zugang") or "")
        clean_values["proben_text"] = clean_values["proben_text"] or str(auto_values.get("ProbenText") or "")
        clean_values["implantat_text"] = clean_values["implantat_text"] or str(auto_values.get("ImplantatText") or "")
        if not clean_values["kommentar"] and auto_values.get("AutomatischExtrahiert"):
            clean_values["kommentar"] = "Automatisch aus OP-Bericht vorbefüllt; bitte prüfen."
        if not targets and not any(clean_values.values()):
            raise ValueError("Keine Datei und kein Berichtstext eingetragen")

        selected_intervention = (
            self.validated_case_intervention(con, case, intervention_id)
            if intervention_id
            else None
        )
        intervention = self.resolve_intervention_for_op_report(
            con,
            case,
            selected_intervention=selected_intervention,
            op_date=clean_values["op_datum"],
            summary=" ".join(
                part
                for part in [
                    clean_values["eingriff_zusammenfassung"],
                    clean_values["implantat_text"],
                    clean_values["proben_text"],
                ]
                if part
            ),
        )
        source_file_id = None
        primary_target = targets[0] if targets else None
        if primary_target is not None:
            source_file_id = self.register_source_file(
                con,
                source_system="OP-Bericht",
                path=primary_target,
                comment=clean_values["kommentar"] or None,
            )
        extracted = {
            "EingriffZusammenfassung": clean_values["eingriff_zusammenfassung"] or None,
            "DiagnoseText": clean_values["diagnose_text"] or None,
            "Operateur": clean_values["operateur"] or None,
            "OPAssistent": clean_values["op_assistent"] or None,
            "Legholder": clean_values["legholder"] or None,
            "Anaesthesist": clean_values["anaesthesist"] or None,
            "Instrumentation": clean_values["instrumentation"] or None,
            "LagerungNarkose": clean_values["lagerung_narkose"] or None,
            "Zugang": clean_values["zugang"] or None,
            "ProbenText": clean_values["proben_text"] or None,
            "ImplantatText": clean_values["implantat_text"] or None,
            "ManuellErfasst": bool(clean_values["bericht_text"]),
            "AutomatischExtrahiert": bool(auto_values.get("AutomatischExtrahiert")),
            "Extraktionsstatus": auto_values.get("Extraktionsstatus"),
            "GefundeneBegriffe": auto_values.get("GefundeneBegriffe") or [],
            "TextZeichen": auto_values.get("TextZeichen"),
            "RohtextGespeichert": auto_values.get("RohtextGespeichert"),
            "ZugeordneterEingriffID": intervention["EingriffID"] if intervention else None,
            "Dateien": [path.name for path in targets],
            "SeitenDateien": [str(path) for path in targets],
            "Seitenzahl": len(targets),
        }
        inferred_reason = self.infer_reoperation_reason_from_text(
            clean_values["eingriff_zusammenfassung"],
            clean_values["implantat_text"],
            clean_values["proben_text"],
            clean_values["bericht_text"],
            clean_values["kommentar"],
        )
        if inferred_reason.get("Kategorie"):
            extracted["Reoperationsgrund"] = inferred_reason
        cur = con.execute(
            """
            INSERT INTO tblOPBerichtDokument (
                EpisodeID, AufenthaltID, EingriffID, SourceFileID, OriginalPath,
                DokumentDatum, OPDatum, EingriffZusammenfassung, Zugang,
                ProbenText, ImplantatText, DiagnoseText, Operateur, OPAssistent,
                Legholder, Anaesthesist, Instrumentation, LagerungNarkose,
                BerichtText, ExtractedJSON,
                ReviewStatus, Kommentar
            )
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'offen', ?)
            """,
            (
                case["EpisodeID"],
                intervention["AufenthaltID"] if intervention else None,
                intervention["EingriffID"] if intervention else None,
                source_file_id,
                str(primary_target) if primary_target is not None else None,
                clean_values["dokument_datum"] or None,
                clean_values["op_datum"] or None,
                clean_values["eingriff_zusammenfassung"] or None,
                clean_values["zugang"] or None,
                clean_values["proben_text"] or None,
                clean_values["implantat_text"] or None,
                clean_values["diagnose_text"] or None,
                clean_values["operateur"] or None,
                clean_values["op_assistent"] or None,
                clean_values["legholder"] or None,
                clean_values["anaesthesist"] or None,
                clean_values["instrumentation"] or None,
                clean_values["lagerung_narkose"] or None,
                clean_values["bericht_text"] or None,
                json.dumps(extracted, ensure_ascii=False),
                clean_values["kommentar"] or None,
            ),
        )
        if intervention:
            con.execute(
                "UPDATE tblEingriff SET KeinOPBerichtErwartet = 0, UpdatedAt = CURRENT_TIMESTAMP WHERE EingriffID = ?",
                (intervention["EingriffID"],),
            )
            self.update_intervention_reoperation_reason_from_text(
                con,
                int(intervention["EingriffID"]),
                source="OP-Bericht",
                texts=(
                    clean_values["eingriff_zusammenfassung"],
                    clean_values["implantat_text"],
                    clean_values["proben_text"],
                    clean_values["bericht_text"],
                    clean_values["kommentar"],
                ),
            )
        self.reassign_microbiology_near_interventions(con, case)
        return int(cur.lastrowid)

    def upload_op_report(self, kollektiv_id: int) -> None:
        form = cgi.FieldStorage(
            fp=self.rfile,
            headers=self.headers,
            environ={
                "REQUEST_METHOD": "POST",
                "CONTENT_TYPE": self.headers.get("content-type", ""),
                "CONTENT_LENGTH": self.headers.get("content-length", "0"),
            },
        )
        nur_orthodok = (form.getfirst("nur_orthodok") or "") == "1"
        file_item = form["file"] if "file" in form else None
        target: Path | None = None
        if not nur_orthodok and file_item is not None and getattr(file_item, "filename", ""):
            try:
                target = self.save_op_report_upload_file(file_item)
            except ValueError as exc:
                self.send_error(HTTPStatus.BAD_REQUEST, explain=str(exc))
                return

        opbericht_pages: list[Path] = []
        if not nur_orthodok:
            try:
                opbericht_pages = self.save_op_report_embedded_pages(
                    form.getfirst("opbericht_pages_json"),
                    filename_prefix="OPBericht",
                )
            except ValueError as exc:
                self.send_error(HTTPStatus.BAD_REQUEST, explain=str(exc))
                return

        values = {
            "eingriff_zusammenfassung": (form.getfirst("eingriff_zusammenfassung") or "").strip(),
            "diagnose_text": (form.getfirst("diagnose_text") or "").strip(),
            "operateur": (form.getfirst("operateur") or "").strip(),
            "op_assistent": (form.getfirst("op_assistent") or "").strip(),
            "legholder": (form.getfirst("legholder") or "").strip(),
            "anaesthesist": (form.getfirst("anaesthesist") or "").strip(),
            "instrumentation": (form.getfirst("instrumentation") or "").strip(),
            "lagerung_narkose": (form.getfirst("lagerung_narkose") or "").strip(),
            "zugang": (form.getfirst("zugang") or "").strip(),
            "proben_text": (form.getfirst("proben_text") or "").strip(),
            "implantat_text": (form.getfirst("implantat_text") or "").strip(),
            "bericht_text": (form.getfirst("bericht_text") or "").strip(),
            "kommentar": (form.getfirst("kommentar") or "").strip(),
            "op_datum": (form.getfirst("op_datum") or "").strip(),
            "dokument_datum": (form.getfirst("dokument_datum") or "").strip(),
        }

        with db_connect(self.db_path) as con:
            case = self.get_kollektiv_case(con, kollektiv_id)
            if not case:
                self.send_error(HTTPStatus.NOT_FOUND, explain="Fallakte nicht gefunden")
                return
            requested_intervention_id = int_or_none(form.getfirst("eingriff_id"))
            if nur_orthodok:
                intervention = self.validated_case_intervention(con, case, requested_intervention_id)
                if not intervention:
                    self.send_error(HTTPStatus.BAD_REQUEST, explain="Bitte den zugehörigen Eingriff auswählen")
                    return
                con.execute(
                    """
                    UPDATE tblEingriff
                    SET KeinOPBerichtErwartet = 1,
                        UpdatedAt = CURRENT_TIMESTAMP
                    WHERE EingriffID = ?
                    """,
                    (requested_intervention_id,),
                )
                con.commit()
                self.redirect(f"/fallakte/{kollektiv_id}/opberichte?eingriff_id={requested_intervention_id}#opberichte")
                return
            try:
                self.create_op_report_document(
                    con,
                    case,
                    intervention_id=requested_intervention_id,
                    target=target,
                    additional_targets=opbericht_pages,
                    values=values,
                )
            except ValueError as exc:
                self.send_error(HTTPStatus.BAD_REQUEST, explain=str(exc))
                return
            con.commit()
        self.redirect(f"/fallakte/{kollektiv_id}/opberichte")

    def upload_clipboard_op_report(self, kollektiv_id: int) -> None:
        max_body = 60 * 1024 * 1024
        length = int(self.headers.get("content-length", "0"))
        if length <= 0:
            self.send_json({"ok": False, "error": "Leerer Upload"}, HTTPStatus.BAD_REQUEST)
            return
        if length > max_body:
            self.send_json({"ok": False, "error": "Datei ist zu gross"}, HTTPStatus.REQUEST_ENTITY_TOO_LARGE)
            return
        try:
            payload = json.loads(self.rfile.read(length).decode("utf-8"))
        except json.JSONDecodeError:
            self.send_json({"ok": False, "error": "Upload konnte nicht gelesen werden"}, HTTPStatus.BAD_REQUEST)
            return

        manual_text = str(payload.get("bericht_text") or "").strip()
        data_url = str(payload.get("image_data") or "")
        target = None
        if data_url:
            match = re.match(r"^data:(image/(?:png|jpeg|jpg|tiff)|application/pdf|text/plain);base64,(.+)$", data_url, re.DOTALL)
            if not match:
                self.send_json({"ok": False, "error": "Nur Bild, PDF oder Text wird unterstützt"}, HTTPStatus.BAD_REQUEST)
                return
            suffix_by_mime = {
                "image/png": ".png",
                "image/jpeg": ".jpg",
                "image/jpg": ".jpg",
                "image/tiff": ".tiff",
                "application/pdf": ".pdf",
                "text/plain": ".txt",
            }
            try:
                upload_bytes = base64.b64decode(match.group(2), validate=True)
            except ValueError:
                self.send_json({"ok": False, "error": "Dateidaten sind ungültig"}, HTTPStatus.BAD_REQUEST)
                return
            if not upload_bytes:
                self.send_json({"ok": False, "error": "Leere Dateidaten"}, HTTPStatus.BAD_REQUEST)
                return
            filename = Path(str(payload.get("filename") or "op_bericht")).name
            suffix = Path(filename).suffix.lower()
            if suffix not in {".pdf", ".png", ".jpg", ".jpeg", ".tif", ".tiff", ".txt"}:
                filename = f"{Path(filename).stem or 'op_bericht'}{suffix_by_mime.get(match.group(1), '.png')}"
            OP_REPORT_DIR.mkdir(parents=True, exist_ok=True)
            target = self.unique_op_report_path(filename)
            target.write_bytes(upload_bytes)

        values = {
            "eingriff_zusammenfassung": str(payload.get("eingriff_zusammenfassung") or "").strip(),
            "diagnose_text": str(payload.get("diagnose_text") or "").strip(),
            "operateur": str(payload.get("operateur") or "").strip(),
            "op_assistent": str(payload.get("op_assistent") or "").strip(),
            "legholder": str(payload.get("legholder") or "").strip(),
            "anaesthesist": str(payload.get("anaesthesist") or "").strip(),
            "instrumentation": str(payload.get("instrumentation") or "").strip(),
            "lagerung_narkose": str(payload.get("lagerung_narkose") or "").strip(),
            "zugang": str(payload.get("zugang") or "").strip(),
            "proben_text": str(payload.get("proben_text") or "").strip(),
            "implantat_text": str(payload.get("implantat_text") or "").strip(),
            "bericht_text": manual_text,
            "kommentar": str(payload.get("kommentar") or "").strip(),
            "op_datum": str(payload.get("op_datum") or "").strip(),
            "dokument_datum": str(payload.get("dokument_datum") or "").strip(),
        }
        if target is None and not any(values.values()):
            self.send_json({"ok": False, "error": "Bitte OP-Bericht-Text oder Datei einfügen"}, HTTPStatus.BAD_REQUEST)
            return

        requested_intervention_id = int_or_none(str(payload.get("eingriff_id") or ""))
        try:
            with db_connect(self.db_path) as con:
                case = self.get_kollektiv_case(con, kollektiv_id)
                if not case:
                    self.send_json({"ok": False, "error": "Fallakte nicht gefunden"}, HTTPStatus.NOT_FOUND)
                    return
                report_id = self.create_op_report_document(
                    con,
                    case,
                    intervention_id=requested_intervention_id,
                    target=target,
                    values=values,
                )
                con.commit()
        except ValueError as exc:
            self.send_json({"ok": False, "error": str(exc)}, HTTPStatus.BAD_REQUEST)
            return
        except Exception as exc:
            self.send_json({"ok": False, "error": str(exc)}, HTTPStatus.INTERNAL_SERVER_ERROR)
            return
        self.send_json(
            {
                "ok": True,
                "opbericht_id": report_id,
                "detail_url": f"/fallakte/{kollektiv_id}/opberichte",
                "stored_path": str(target) if target is not None else "",
            }
        )

    def update_op_report(self, kollektiv_id: int, form: dict[str, list[str]]) -> None:
        report_id = int_or_none(first(form.get("opbericht_id")))
        if not report_id:
            self.send_error(HTTPStatus.BAD_REQUEST, explain="OP-Bericht fehlt")
            return
        status = (first(form.get("review_status")) or "offen").strip()
        if status not in {"offen", "unklar", "bearbeitet", "bestaetigt"}:
            status = "offen"
        with db_connect(self.db_path) as con:
            case = self.get_kollektiv_case(con, kollektiv_id)
            if not case:
                self.send_error(HTTPStatus.NOT_FOUND, explain="Fallakte nicht gefunden")
                return
            report = con.execute(
                """
                SELECT OPBerichtDokumentID
                FROM tblOPBerichtDokument
                WHERE OPBerichtDokumentID = ? AND EpisodeID = ?
                """,
                (report_id, case["EpisodeID"]),
            ).fetchone()
            if not report:
                self.send_error(HTTPStatus.NOT_FOUND, explain="OP-Bericht nicht gefunden")
                return
            requested_intervention_id = int_or_none(first(form.get("eingriff_id")))
            selected_intervention = (
                self.validated_case_intervention(con, case, requested_intervention_id)
                if requested_intervention_id
                else None
            )
            clean_values = {
                "dokument_datum": (first(form.get("dokument_datum")) or "").strip(),
                "op_datum": (first(form.get("op_datum")) or "").strip(),
                "eingriff_zusammenfassung": (first(form.get("eingriff_zusammenfassung")) or "").strip(),
                "diagnose_text": (first(form.get("diagnose_text")) or "").strip(),
                "operateur": (first(form.get("operateur")) or "").strip(),
                "op_assistent": (first(form.get("op_assistent")) or "").strip(),
                "legholder": (first(form.get("legholder")) or "").strip(),
                "anaesthesist": (first(form.get("anaesthesist")) or "").strip(),
                "instrumentation": (first(form.get("instrumentation")) or "").strip(),
                "lagerung_narkose": (first(form.get("lagerung_narkose")) or "").strip(),
                "zugang": (first(form.get("zugang")) or "").strip(),
                "proben_text": (first(form.get("proben_text")) or "").strip(),
                "implantat_text": (first(form.get("implantat_text")) or "").strip(),
                "bericht_text": (first(form.get("bericht_text")) or "").strip(),
                "kommentar": (first(form.get("kommentar")) or "").strip(),
            }
            intervention = self.resolve_intervention_for_op_report(
                con,
                case,
                selected_intervention=selected_intervention,
                op_date=clean_values["op_datum"],
                summary=" ".join(
                    part
                    for part in [
                        clean_values["eingriff_zusammenfassung"],
                        clean_values["implantat_text"],
                        clean_values["proben_text"],
                    ]
                    if part
                ),
            )
            con.execute(
                """
                UPDATE tblOPBerichtDokument
                SET AufenthaltID = ?,
                    EingriffID = ?,
                    DokumentDatum = ?,
                    OPDatum = ?,
                    EingriffZusammenfassung = ?,
                    DiagnoseText = ?,
                    Operateur = ?,
                    OPAssistent = ?,
                    Legholder = ?,
                    Anaesthesist = ?,
                    Instrumentation = ?,
                    LagerungNarkose = ?,
                    Zugang = ?,
                    ProbenText = ?,
                    ImplantatText = ?,
                    BerichtText = ?,
                    ReviewStatus = ?,
                    Kommentar = ?
                WHERE OPBerichtDokumentID = ? AND EpisodeID = ?
                """,
                (
                    intervention["AufenthaltID"] if intervention else None,
                    intervention["EingriffID"] if intervention else None,
                    clean_values["dokument_datum"] or None,
                    clean_values["op_datum"] or None,
                    clean_values["eingriff_zusammenfassung"] or None,
                    clean_values["diagnose_text"] or None,
                    clean_values["operateur"] or None,
                    clean_values["op_assistent"] or None,
                    clean_values["legholder"] or None,
                    clean_values["anaesthesist"] or None,
                    clean_values["instrumentation"] or None,
                    clean_values["lagerung_narkose"] or None,
                    clean_values["zugang"] or None,
                    clean_values["proben_text"] or None,
                    clean_values["implantat_text"] or None,
                    clean_values["bericht_text"] or None,
                    status,
                    clean_values["kommentar"] or None,
                    report_id,
                    case["EpisodeID"],
                ),
            )
            if intervention:
                self.update_intervention_reoperation_reason_from_text(
                    con,
                    int(intervention["EingriffID"]),
                    source="OP-Bericht",
                    texts=(
                        clean_values["eingriff_zusammenfassung"],
                        clean_values["implantat_text"],
                        clean_values["proben_text"],
                        clean_values["bericht_text"],
                        clean_values["kommentar"],
                    ),
                )
            self.reassign_microbiology_near_interventions(con, case)
            con.commit()
        self.redirect(f"/fallakte/{kollektiv_id}/opberichte#opbericht-{report_id}")

    def delete_op_report(self, kollektiv_id: int, form: dict[str, list[str]]) -> None:
        report_id = int_or_none(first(form.get("opbericht_id")))
        if not report_id:
            self.send_error(HTTPStatus.BAD_REQUEST, explain="OP-Bericht fehlt")
            return
        with db_connect(self.db_path) as con:
            case = self.get_kollektiv_case(con, kollektiv_id)
            if not case:
                self.send_error(HTTPStatus.NOT_FOUND, explain="Fallakte nicht gefunden")
                return
            current = con.execute(
                """
                SELECT OPBerichtDokumentID, Kommentar
                FROM tblOPBerichtDokument
                WHERE OPBerichtDokumentID = ? AND EpisodeID = ?
                """,
                (report_id, case["EpisodeID"]),
            ).fetchone()
            if not current:
                self.send_error(HTTPStatus.NOT_FOUND, explain="OP-Bericht nicht gefunden")
                return
            note = "aus Arbeitsansicht ausgeblendet"
            comment = " | ".join(part for part in [current["Kommentar"], note] if part)
            if self.column_exists(con, "tblOPBerichtDokument", "UpdatedAt"):
                con.execute(
                    """
                    UPDATE tblOPBerichtDokument
                    SET ReviewStatus = 'geloescht',
                        Kommentar = ?,
                        UpdatedAt = CURRENT_TIMESTAMP
                    WHERE OPBerichtDokumentID = ? AND EpisodeID = ?
                    """,
                    (comment, report_id, case["EpisodeID"]),
                )
            else:
                con.execute(
                    """
                    UPDATE tblOPBerichtDokument
                    SET ReviewStatus = 'geloescht',
                        Kommentar = ?
                    WHERE OPBerichtDokumentID = ? AND EpisodeID = ?
                    """,
                    (comment, report_id, case["EpisodeID"]),
                )
            self.reassign_microbiology_near_interventions(con, case)
            con.commit()
        self.redirect(f"/fallakte/{kollektiv_id}/opberichte")

    def upload_clipboard_fever_curve(self) -> None:
        max_body = 60 * 1024 * 1024
        length = int(self.headers.get("content-length", "0"))
        if length <= 0:
            self.send_json({"ok": False, "error": "Leerer Upload"}, HTTPStatus.BAD_REQUEST)
            return
        if length > max_body:
            self.send_json({"ok": False, "error": "Datei ist zu gross"}, HTTPStatus.REQUEST_ENTITY_TOO_LARGE)
            return
        try:
            payload = json.loads(self.rfile.read(length).decode("utf-8"))
        except json.JSONDecodeError:
            self.send_json({"ok": False, "error": "Upload konnte nicht gelesen werden"}, HTTPStatus.BAD_REQUEST)
            return

        data_url = str(payload.get("image_data") or "")
        match = re.match(r"^data:(image/(?:png|jpeg|jpg|tiff)|application/pdf);base64,(.+)$", data_url, re.DOTALL)
        if not match:
            self.send_json({"ok": False, "error": "Nur Bild oder PDF wird unterstützt"}, HTTPStatus.BAD_REQUEST)
            return
        mime_type = match.group(1)
        suffix_by_mime = {
            "image/png": ".png",
            "image/jpeg": ".jpg",
            "image/jpg": ".jpg",
            "image/tiff": ".tiff",
            "application/pdf": ".pdf",
        }
        try:
            upload_bytes = base64.b64decode(match.group(2), validate=True)
        except ValueError:
            self.send_json({"ok": False, "error": "Dateidaten sind ungültig"}, HTTPStatus.BAD_REQUEST)
            return
        if not upload_bytes:
            self.send_json({"ok": False, "error": "Leere Dateidaten"}, HTTPStatus.BAD_REQUEST)
            return

        filename = Path(str(payload.get("filename") or "fieberkurve")).name
        suffix = Path(filename).suffix.lower()
        if suffix not in {".pdf", ".png", ".jpg", ".jpeg", ".tif", ".tiff"}:
            filename = f"{Path(filename).stem or 'fieberkurve'}{suffix_by_mime.get(mime_type, '.png')}"
        UPLOAD_DIR.mkdir(parents=True, exist_ok=True)
        target = self.unique_upload_path(filename)
        target.write_bytes(upload_bytes)

        episode_id = int_or_none(str(payload.get("episode_id") or ""))
        intervention_id = int_or_none(str(payload.get("eingriff_id") or ""))
        stay_id = int_or_none(str(payload.get("aufenthalt_id") or ""))
        replace_value = payload.get("replace_existing")
        replace_existing = (
            replace_value
            if isinstance(replace_value, bool)
            else str(replace_value or "").strip().lower() in {"1", "true", "yes", "on"}
        )
        try:
            fever_id = self.create_review_packet(
                target,
                replace_existing=replace_existing,
                episode_id=episode_id,
                intervention_id=intervention_id,
                stay_id=stay_id,
                redirect_to_review=False,
            )
        except Exception as exc:
            self.send_json({"ok": False, "error": str(exc)}, HTTPStatus.INTERNAL_SERVER_ERROR)
            return
        if fever_id is None:
            return
        self.send_json(
            {
                "ok": True,
                "fieberkurve_id": fever_id,
                "review_url": f"/review/{fever_id}",
                "stored_path": str(target),
                "staged": True,
            }
        )

    def import_fever_curve_path(self, form: dict[str, list[str]]) -> None:
        source = Path(first(form.get("source_path"))).expanduser()
        if not source.exists() or not source.is_file():
            self.send_error(HTTPStatus.BAD_REQUEST, explain="Datei nicht gefunden")
            return
        suffix = source.suffix.lower()
        if suffix not in {".pdf", ".png", ".jpg", ".jpeg", ".tif", ".tiff"}:
            self.send_error(HTTPStatus.BAD_REQUEST, explain="Nur PDF- und Bilddateien werden akzeptiert")
            return
        replace_existing = first(form.get("replace_existing")) == "1"
        episode_id = int_or_none(first(form.get("episode_id")))
        intervention_id = int_or_none(first(form.get("eingriff_id")))
        stay_id = int_or_none(first(form.get("aufenthalt_id")))
        self.create_review_packet(
            source,
            replace_existing=replace_existing,
            episode_id=episode_id,
            intervention_id=intervention_id,
            stay_id=stay_id,
        )

    def unique_upload_path(self, filename: str) -> Path:
        stem = Path(filename).stem[:80] or "fieberkurve"
        suffix = Path(filename).suffix.lower()
        candidate = UPLOAD_DIR / f"{stem}{suffix}"
        if not candidate.exists():
            return candidate
        stamp = time.strftime("%Y%m%d-%H%M%S")
        return UPLOAD_DIR / f"{stem}-{stamp}{suffix}"

    def create_review_packet(
        self,
        source: Path,
        *,
        replace_existing: bool,
        episode_id: int | None = None,
        intervention_id: int | None = None,
        stay_id: int | None = None,
        redirect_to_review: bool = True,
    ) -> int | None:
        # First collect all sheets. OCR is intentionally deferred until the
        # reviewer starts one combined extraction from the review page.
        packet = self.staged_fever_packet(source)
        insert_review_packet(self.db_path, packet, replace_existing=replace_existing)
        fever_id = packet.get("database_fieberkurve_id")
        if fever_id and (episode_id or intervention_id or stay_id):
            with db_connect(self.db_path) as con:
                try:
                    self.assign_fever_curve(con, int(fever_id), episode_id, intervention_id, stay_id=stay_id)
                except ValueError as exc:
                    self.send_error(HTTPStatus.BAD_REQUEST, explain=str(exc))
                    return None
                con.commit()
        if redirect_to_review:
            self.redirect(f"/review/{fever_id}" if fever_id else "/")
        return int(fever_id) if fever_id else None

    def assign_fever_curve(
        self,
        con: sqlite3.Connection,
        fever_id: int,
        episode_id: int | None,
        intervention_id: int | None,
        *,
        stay_id: int | None = None,
    ) -> tuple[int | None, int | None]:
        if intervention_id:
            found = con.execute(
                """
                SELECT a.EpisodeID, e.AufenthaltID
                FROM tblEingriff e
                JOIN tblAufenthalt a ON a.AufenthaltID = e.AufenthaltID
                WHERE e.EingriffID = ?
                """,
                (intervention_id,),
            ).fetchone()
            if not found:
                raise ValueError("EingriffID nicht gefunden")
            episode_id = episode_id or int(found["EpisodeID"])
            stay_id = int(found["AufenthaltID"]) if found["AufenthaltID"] is not None else None
        elif stay_id:
            found = con.execute(
                """
                SELECT EpisodeID
                FROM tblAufenthalt
                WHERE AufenthaltID = ?
                """,
                (stay_id,),
            ).fetchone()
            if not found:
                raise ValueError("AufenthaltID nicht gefunden")
            episode_id = episode_id or int(found["EpisodeID"])
        if episode_id:
            exists = con.execute("SELECT 1 FROM tblEpisode WHERE EpisodeID = ?", (episode_id,)).fetchone()
            if not exists:
                raise ValueError("EpisodeID nicht gefunden")
        con.execute(
            """
            UPDATE tblFieberkurve
            SET EpisodeID = ?, AufenthaltID = COALESCE(AufenthaltID, ?), EingriffID = ?
            WHERE FieberkurveID = ?
            """,
            (episode_id, stay_id, intervention_id, fever_id),
        )
        if stay_id:
            self.fill_fever_range_from_stay(con, fever_id, stay_id)
        con.execute(
            """
            UPDATE tblFieberkurveMedikamentKandidat
            SET EpisodeID = COALESCE(EpisodeID, ?),
                EingriffID = COALESCE(EingriffID, ?)
            WHERE FieberkurveID = ?
            """,
            (episode_id, intervention_id, fever_id),
        )
        if episode_id and self.table_exists(con, "tblFieberkurveKollektiv"):
            con.execute(
                """
                UPDATE tblFieberkurveKollektiv
                SET FieberkurveStatus = 'vorhanden',
                    SAPScreenshotStatus = CASE
                        WHEN SAPScreenshotStatus IN ('offen', 'exportiert') THEN 'importiert'
                        ELSE SAPScreenshotStatus
                    END,
                    FieberkurveIDs = (
                        SELECT GROUP_CONCAT(FieberkurveID)
                        FROM tblFieberkurve
                        WHERE EpisodeID = ?
                    ),
                    UpdatedAt = CURRENT_TIMESTAMP
                WHERE EpisodeID = ? AND KollektivName = ?
                """,
                (episode_id, episode_id, KOLLEKTIV_NAME),
            )
        return episode_id, intervention_id

    def fill_fever_range_from_stay(self, con: sqlite3.Connection, fever_id: int, stay_id: int) -> None:
        """Fill only missing fever-curve dates from its linked stay/patient letter."""
        dates = con.execute(
            """
            SELECT
                COALESCE(
                    (SELECT MIN(NULLIF(p.Aufnahme, ''))
                     FROM tblPatientenbriefDokument p
                     WHERE p.AufenthaltID = a.AufenthaltID
                       AND COALESCE(p.ReviewStatus, 'offen') <> 'geloescht'),
                    NULLIF(a.Aufnahme, '')
                ) AS Beginn,
                COALESCE(
                    (SELECT MAX(NULLIF(p.Entlassung, ''))
                     FROM tblPatientenbriefDokument p
                     WHERE p.AufenthaltID = a.AufenthaltID
                       AND COALESCE(p.ReviewStatus, 'offen') <> 'geloescht'),
                    NULLIF(a.Entlassung, '')
                ) AS Ende
            FROM tblAufenthalt a
            WHERE a.AufenthaltID = ?
            """,
            (stay_id,),
        ).fetchone()
        if not dates:
            return
        start = iso_date_or_blank(dates["Beginn"])
        end = iso_date_or_blank(dates["Ende"])
        if start and end and start > end:
            return
        con.execute(
            """
            UPDATE tblFieberkurve
            SET VonDatum = COALESCE(NULLIF(VonDatum, ''), ?),
                BisDatum = COALESCE(NULLIF(BisDatum, ''), ?)
            WHERE FieberkurveID = ?
            """,
            (start or None, end or None, fever_id),
        )

    def episode_id_for_intervention(self, con: sqlite3.Connection, intervention_id: int) -> int | None:
        row = con.execute(
            """
            SELECT a.EpisodeID
            FROM tblEingriff e
            JOIN tblAufenthalt a ON a.AufenthaltID = e.AufenthaltID
            WHERE e.EingriffID = ?
            """,
            (intervention_id,),
        ).fetchone()
        return int(row["EpisodeID"]) if row and row["EpisodeID"] is not None else None

    def upsert_episode_therapy_from_study(
        self,
        con: sqlite3.Connection,
        episode_id: int,
        intervention_id: int | None,
        values: dict[str, object],
    ) -> None:
        phases = [
            (
                "empirisch",
                values.get("EmpirischeAB"),
                values.get("EmpirischeStart"),
                values.get("EmpirischeEnde"),
                values.get("EmpirischeStartZeit"),
                values.get("EmpirischeEndeZeit"),
                values.get("EmpiricalCoverageStatus"),
            ),
            (
                "gezielt",
                values.get("GezielteAB"),
                values.get("GezielteStart"),
                values.get("GezielteEnde"),
                values.get("GezielteStartZeit"),
                values.get("GezielteEndeZeit"),
                "targeted",
            ),
        ]
        for phase, antibiotic, start, end, start_time, end_time, coverage_status in phases:
            if not antibiotic:
                continue
            existing = con.execute(
                """
                SELECT AntibiotikatherapieID
                FROM tblAntibiotikatherapie
                WHERE EpisodeID = ?
                  AND Therapiephase = ?
                  AND Antibiotikum = ?
                  AND COALESCE(Start, '') = COALESCE(?, '')
                ORDER BY AntibiotikatherapieID DESC
                LIMIT 1
                """,
                (episode_id, phase, antibiotic, start),
            ).fetchone()
            if existing:
                con.execute(
                    """
                    UPDATE tblAntibiotikatherapie
                    SET EingriffID = ?, Ende = ?, StartZeit = ?, EndeZeit = ?,
                        Kommentar = ?, Reviewer = ?,
                        AktivGegenErreger = ?,
                        CoverageStatus = ?,
                        AbgleichStatus = ?,
                        AbgleichKommentar = ?,
                        BekannteErregerText = ?,
                        ReviewStatus = 'bestaetigt', Quelle = 'ReviewApp',
                        UpdatedAt = CURRENT_TIMESTAMP
                    WHERE AntibiotikatherapieID = ?
                    """,
                    (
                        intervention_id,
                        end,
                        start_time,
                        end_time,
                        values.get("Kommentar"),
                        values.get("Reviewer"),
                        values.get("EmpirischAktivGegenErreger") if phase == "empirisch" else None,
                        coverage_status,
                        values.get("EmpirischBewertung") if phase == "empirisch" else None,
                        values.get("EmpirischBewertungsgrund") if phase == "empirisch" else None,
                        values.get("ErregerZumTherapiezeitpunkt") if phase == "empirisch" else None,
                        existing["AntibiotikatherapieID"],
                    ),
                )
            else:
                con.execute(
                    """
                    INSERT INTO tblAntibiotikatherapie (
                        EpisodeID, EingriffID, Therapiephase, Antibiotikum,
                        Start, Ende, StartZeit, EndeZeit, AktivGegenErreger,
                        CoverageStatus, AbgleichStatus,
                        AbgleichKommentar, BekannteErregerText,
                        Kommentar, Reviewer, ReviewStatus, Quelle
                    )
                    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'bestaetigt', 'ReviewApp')
                    """,
                    (
                        episode_id,
                        intervention_id,
                        phase,
                        antibiotic,
                        start,
                        end,
                        start_time,
                        end_time,
                        values.get("EmpirischAktivGegenErreger") if phase == "empirisch" else None,
                        coverage_status,
                        values.get("EmpirischBewertung") if phase == "empirisch" else None,
                        values.get("EmpirischBewertungsgrund") if phase == "empirisch" else None,
                        values.get("ErregerZumTherapiezeitpunkt") if phase == "empirisch" else None,
                        values.get("Kommentar"),
                        values.get("Reviewer"),
                    ),
                )

    def remove_candidate_antibiotic_administration(self, con: sqlite3.Connection, candidate_id: int) -> None:
        con.execute("DELETE FROM tblAntibiotikaGabe WHERE KandidatID = ?", (candidate_id,))
        con.execute("DELETE FROM tblAntibiotikatherapie WHERE KandidatID = ?", (candidate_id,))

    def upsert_antibiotic_administration(
        self,
        con: sqlite3.Connection,
        candidate_id: int,
        episode_id: int,
        intervention_id: int | None,
        med_norm: str,
        dose: str,
        start: str,
        end: str | None,
        therapy_phase: str | None,
        comment: str,
    ) -> None:
        existing = con.execute(
            "SELECT AntibiotikaGabeID FROM tblAntibiotikaGabe WHERE KandidatID = ?",
            (candidate_id,),
        ).fetchone()
        if existing:
            con.execute(
                """
                UPDATE tblAntibiotikaGabe
                SET EpisodeID = ?, EingriffID = ?, Therapiephase = ?, Antibiotikum = ?,
                    Dosis = ?, Start = ?, Ende = ?, Kommentar = ?,
                    BestaetigtAm = CURRENT_TIMESTAMP
                WHERE AntibiotikaGabeID = ?
                """,
                (
                    episode_id,
                    intervention_id,
                    therapy_phase,
                    med_norm,
                    dose,
                    start,
                    end,
                    comment,
                    existing["AntibiotikaGabeID"],
                ),
            )
        else:
            if intervention_id:
                con.execute(
                    """
                    INSERT INTO tblAntibiotikaGabe (
                        EpisodeID, EingriffID, KandidatID, Therapiephase, Antibiotikum,
                        Dosis, Start, Ende, Kommentar, BestaetigtAm
                    )
                    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP)
                    """,
                    (episode_id, intervention_id, candidate_id, therapy_phase, med_norm, dose, start, end, comment),
                )
        existing_therapy = con.execute(
            """
            SELECT AntibiotikatherapieID
            FROM tblAntibiotikatherapie
            WHERE KandidatID = ?
            """,
            (candidate_id,),
        ).fetchone()
        if existing_therapy:
            con.execute(
                """
                UPDATE tblAntibiotikatherapie
                SET EpisodeID = ?, EingriffID = ?, Therapiephase = ?, Antibiotikum = ?, Dosis = ?,
                    Start = ?, Ende = ?, Kommentar = ?, ReviewStatus = 'bestaetigt',
                    Quelle = 'ReviewApp', UpdatedAt = CURRENT_TIMESTAMP
                WHERE AntibiotikatherapieID = ?
                """,
                (
                    episode_id,
                    intervention_id,
                    therapy_phase,
                    med_norm,
                    dose,
                    start,
                    end,
                    comment,
                    existing_therapy["AntibiotikatherapieID"],
                ),
            )
        else:
            con.execute(
                """
                INSERT INTO tblAntibiotikatherapie (
                    EpisodeID, EingriffID, KandidatID, Therapiephase, Antibiotikum, Dosis,
                    Start, Ende, Kommentar, ReviewStatus, Quelle
                )
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 'bestaetigt', 'ReviewApp')
                """,
                (episode_id, intervention_id, candidate_id, therapy_phase, med_norm, dose, start, end, comment),
            )

    def serve_image(self, page_id: int) -> None:
        with db_connect(self.db_path) as con:
            row = con.execute(
                "SELECT BildPfad FROM tblFieberkurveSeite WHERE FieberkurveSeiteID = ?",
                (page_id,),
            ).fetchone()
        if not row or not row["BildPfad"]:
            self.send_error(HTTPStatus.NOT_FOUND)
            return
        path = Path(row["BildPfad"]).expanduser()
        if not path.exists() or not path.is_file():
            self.send_error(HTTPStatus.NOT_FOUND)
