def main() -> None:
    parser = argparse.ArgumentParser(description="Run the local PJI fever-curve review app.")
    parser.add_argument("--db", default=DEFAULT_DB, type=Path)
    parser.add_argument("--host", default="127.0.0.1")
    parser.add_argument("--port", default=8765, type=int)
    args = parser.parse_args()

    if not args.db.exists():
        raise SystemExit(f"Database not found: {args.db}")

    resolved_db = args.db.resolve()
    lock_path = resolved_db.with_name(f".{resolved_db.name}.review_app.lock")
    lock_file = lock_path.open("a+")
    try:
        fcntl.flock(lock_file.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
    except BlockingIOError:
        raise SystemExit(
            f"Another PJI review app is already using this database: {resolved_db}"
        )

    server = ThreadingHTTPServer((args.host, args.port), ReviewApp)
    server.db_path = resolved_db  # type: ignore[attr-defined]
    server.db_lock_file = lock_file  # type: ignore[attr-defined]
    print(f"PJI review app running on http://{args.host}:{args.port}")
    print(f"Database: {server.db_path}")
    server.serve_forever()


if __name__ == "__main__":
    main()
